function communityPage(){let tabs=`<div class="seg"><button class="${state.communityTab==='announcements'?'active':''}" onclick="setCommunityTab('announcements')">الإعلانات</button><button class="${state.communityTab==='forum'?'active':''}" onclick="setCommunityTab('forum')">منتدى الحلقة</button></div>`;if(state.communityTab==='announcements'){let filters=['all','daily','monthly','schedule','achievement','urgent'];let f=`<div class="tabs" style="margin-top:12px">${filters.map(x=>`<button class="tab ${state.announcementFilter===x?'active':''}" onclick="setAnnouncementFilter('${x}')">${x==='all'?'الكل':categoryAr[x]}</button>`).join('')}</div>`;let rows=state.announcements.filter(a=>state.announcementFilter==='all'||a.category===state.announcementFilter);return `${tabs}${f}<div class="section-head"><h3>إعلانات الحلقة</h3>${roleCanManage()?'<button class="btn btn-primary" onclick="openAnnouncement()">+ إعلان</button>':''}</div>${announcementCards(rows)}`}
let addBtn=roleCanManage()?'<button class="btn btn-primary" onclick="openForum()">+ منشور</button>':`<button class="btn btn-primary" onclick="openForum(null,'question')">+ استفسار</button>`;return `${tabs}<div class="section-head"><h3>منتدى الحلقة</h3>${addBtn}</div><div class="notice">ولي الأمر يستطيع طرح استفسار والتعليق. صاحب المنشور يعدّل منشوره، وصاحب التعليق يعدّل تعليقه، والإدارة تستطيع الإشراف على المحتوى.</div><div style="height:10px"></div>${forumCards()}`}
function setCommunityTab(t){state.communityTab=t;setFab();render()}function setAnnouncementFilter(f){state.announcementFilter=f;render()}
function announcementCards(rows=state.announcements){if(!rows.length)return '<div class="empty">لا توجد إعلانات في هذا القسم.</div>';return rows.map(a=>`<div class="card announcement"><div class="row"><div class="grow"><b>${a.pinned?'📌 ':''}${esc(a.title)}</b><div class="muted">${categoryAr[a.category]||'عام'} · ${new Date(a.publish_at).toLocaleDateString('ar-EG-u-nu-latn')}</div></div><span class="badge ${a.priority==='urgent'?'red':a.priority==='important'?'warn':''}">${a.priority==='urgent'?'عاجل':a.priority==='important'?'مهم':'إعلان'}</span></div><p style="margin-bottom:0;white-space:pre-wrap">${esc(a.body)}</p>${roleCanManage()?`<div class="actions"><button class="mini red" onclick="deleteAnnouncement('${a.id}')">إزالة الإعلان</button></div>`:''}</div>`).join('')}
async function deleteAnnouncement(id){if(!roleCanManage())return;if(!confirm('إزالة هذا الإعلان؟'))return;let {error}=await db.from('announcements').delete().eq('id',id);if(error)return toast(error.message);state.announcements=state.announcements.filter(x=>x.id!==id);toast('تمت إزالة الإعلان');render()}
function canEditPost(p){return state.demo||p.author_id===state.user?.id||roleCanManage()}function canEditComment(c){return state.demo||c.author_id===state.user?.id||roleCanManage()}
function forumCards(){if(!state.forum.length)return '<div class="empty">لا توجد منشورات بعد.</div>';return state.forum.map(p=>{let cs=state.comments.filter(c=>c.post_id===p.id);return `<div class="card forum-card"><div class="row"><div class="grow"><b>${p.pinned?'📌 ':''}${esc(p.title)}</b><div class="muted">${esc(p.author_name||'عضو الحلقة')} · ${new Date(p.created_at).toLocaleDateString('ar-EG-u-nu-latn')} ${p.updated_at&&p.updated_at!==p.created_at?'<span class="edited">· تم التعديل</span>':''}</div></div><span class="badge">${p.post_type==='question'?'استفسار':p.post_type==='achievement'?'إنجاز':p.post_type==='notice'?'ملاحظة':'نقاش'}</span></div><p style="white-space:pre-wrap">${esc(p.body)}</p><div class="forum-tools">${canEditPost(p)?`<button class="mini" onclick="openForum('${p.id}')">تعديل المنشور</button>`:''}${canEditPost(p)?`<button class="mini red" onclick="deleteForumPost('${p.id}')">حذف</button>`:''}<span class="badge">💬 ${cs.length}</span></div>${p.comments_enabled===false?'<div class="muted" style="margin-top:8px">التعليقات مغلقة لهذا المنشور.</div>':`<div class="forum-comments">${cs.map(c=>commentHtml(c)).join('')||'<div class="muted">لا توجد تعليقات بعد.</div>'}<div class="comment-form"><textarea id="comment_${p.id}" rows="2" placeholder="اكتب تعليقك أو استفسارك..."></textarea><button class="btn btn-soft" onclick="submitForumComment('${p.id}')">إرسال</button></div></div>`}</div>`}).join('')}
function commentHtml(c){return `<div class="comment"><div class="comment-head"><b>${esc(c.author_name|| (c.author_id===state.user?.id?'أنت':'عضو الحلقة'))}</b><span class="muted">${new Date(c.created_at).toLocaleDateString('ar-EG-u-nu-latn')}</span>${c.updated_at&&c.updated_at!==c.created_at?'<span class="edited">تم التعديل</span>':''}<span class="grow"></span>${canEditComment(c)?`<button class="mini" onclick="editForumComment('${c.id}')">تعديل</button><button class="mini red" onclick="deleteForumComment('${c.id}')">حذف</button>`:''}</div><div class="comment-body">${esc(c.body)}</div></div>`}
async function submitForumComment(postId){let el=$('#comment_'+postId),body=el?.value.trim();if(!body)return toast('اكتب التعليق أولاً');if(state.demo){state.comments.push({id:'c'+Date.now(),post_id:postId,author_id:state.user.id,author_name:state.profile.full_name,body,created_at:new Date().toISOString(),updated_at:new Date().toISOString()});render();return}let {data,error}=await db.from('forum_comments').insert({post_id:postId,author_id:state.user.id,body}).select().single();if(error)return toast(error.message);state.comments.push(data);render()}
function editForumComment(id){let c=state.comments.find(x=>x.id===id);if(!c)return;$('#fcId').value=id;$('#fcBody').value=c.body;commentDlg.showModal()}
$('#commentForm').addEventListener('submit',async e=>{e.preventDefault();let id=$('#fcId').value,body=$('#fcBody').value.trim();if(!body)return;if(state.demo){let c=state.comments.find(x=>x.id===id);c.body=body;c.updated_at=new Date().toISOString()}else{let {data,error}=await db.from('forum_comments').update({body}).eq('id',id).select().single();if(error)return toast(error.message);state.comments[state.comments.findIndex(x=>x.id===id)]=data}commentDlg.close();toast('تم تعديل التعليق');render()})
async function deleteForumComment(id){if(!confirm('حذف التعليق؟'))return;if(state.demo)state.comments=state.comments.filter(x=>x.id!==id);else{let {error}=await db.from('forum_comments').delete().eq('id',id);if(error)return toast(error.message);state.comments=state.comments.filter(x=>x.id!==id)}render()}
async function deleteForumPost(id){if(!confirm('حذف المنشور وتعليقاته؟'))return;if(state.demo){state.forum=state.forum.filter(x=>x.id!==id);state.comments=state.comments.filter(x=>x.post_id!==id)}else{let {error}=await db.from('forum_posts').delete().eq('id',id);if(error)return toast(error.message);state.forum=state.forum.filter(x=>x.id!==id);state.comments=state.comments.filter(x=>x.post_id!==id)}render()}

function plansPage(){let rows=state.students.map(s=>({s,g:state.goals.find(g=>g.student_id===s.id),m:state.monthly.find(m=>m.student_id===s.id)||{}}));return `<div class="hero"><h2>الخطط الشهرية</h2><p>حدد المطلوب من الطالب خلال الشهر، ويحسب التطبيق الورد اليومي ومقدار الإنجاز.</p></div><div class="section-head"><h3>خطط الشهر</h3>${roleCanManage()?'<button class="btn btn-primary" onclick="openPlan()">+ خطة</button>':''}</div>${rows.map(({s,g,m})=>{if(!g)return `<div class="card row">${avatarHtml(s)}<div class="grow"><b>${s.full_name}</b><div class="muted">لا توجد خطة لهذا الشهر</div></div>${roleCanManage()?`<button class="mini" onclick="openPlan('${s.id}')">إضافة</button>`:''}</div>`;let hp=Math.min(100,Math.round(Number(m.hifz_pages||0)/Math.max(Number(g.target_hifz_pages||1),1)*100)),rp=Math.min(100,Math.round(Number(m.review_pages||0)/Math.max(Number(g.target_review_pages||1),1)*100)),sp=Math.min(100,Math.round(Number(m.sard_pages||0)/Math.max(Number(g.target_sard_pages||1),1)*100));return `<div class="card"><div class="row">${avatarHtml(s)}<div class="grow"><b>${s.full_name}</b><div class="muted">الورد اليومي: حفظ ${fmt(g.target_daily_hifz_pages)} · مراجعة ${fmt(g.target_daily_review_pages)} · سرد ${fmt(g.target_daily_sard_pages)} صفحة</div></div></div>${planProgress('الحفظ',hp,m.hifz_pages,g.target_hifz_pages)}${planProgress('المراجعة',rp,m.review_pages,g.target_review_pages)}${planProgress('السرد',sp,m.sard_pages,g.target_sard_pages)}</div>`}).join('')}`}
function planProgress(label,pct,done,target){return `<div class="plan-bar"><div class="plan-label"><span>${label}: ${fmt(done)} / ${fmt(target)} صفحة</span><b>${pct}%</b></div><div class="progress"><i style="width:${pct}%"></i></div></div>`}

function reportStudents(){return activeStudents()}
function reportRowMonthly(st){let r=state.monthly.find(x=>x.student_id===st.id)||{};return {student:st,stats:r}}
function reportHeaderHtml(title,subtitle){let org=state.settings?.organization_name||'حلقتي',hqs=[...new Set(reportStudents().map(s=>state.halaqas.find(h=>h.id===s.halaqa_id)?.name).filter(Boolean))];return `<div class="report-brand"><div class="mark">ح</div><h2>${esc(org)}</h2><p>${esc(title)}</p></div><div class="report-meta"><span><b>الفترة:</b> ${esc(subtitle)}</span><span><b>الحلقة:</b> ${esc(hqs.join('، ')||'—')}</span><span><b>تاريخ الإصدار:</b> ${new Date().toLocaleDateString('ar-EG-u-nu-latn')}</span></div>`}
function reportFooterHtml(){return `<div class="report-footer"><span>تقرير صادر من نظام حلقتي — يعتمد على البيانات الفعلية المسجلة في النظام</span><span dir="ltr">Designed by ${esc(state.settings?.designed_by||'Dr. Mohammed Samir')}</span></div>`}
function monthlyReportHtml(){let rows=reportStudents().map(reportRowMonthly),sum=k=>rows.reduce((a,x)=>a+Number(x.stats[k]||0),0);return `<div class="report-paper">${reportHeaderHtml('التقرير الشهري لأداء الطلاب',monthStart().slice(0,7))}<div class="report-summary"><div><b>${rows.length}</b>طالب</div><div><b>${fmt(sum('hifz_pages'))}</b>صفحة حفظ</div><div><b>${fmt(sum('review_pages'))}</b>صفحة مراجعة</div><div><b>${fmt(sum('sard_pages'))}</b>صفحة سرد</div></div><div style="overflow:auto"><table class="report-table"><thead><tr><th>#</th><th>الطالب</th><th>الفئة</th><th>المسار</th><th>الحفظ</th><th>المراجعة</th><th>السرد</th><th>حضور</th><th>غياب</th><th>بعذر</th><th>تأخر</th><th>أخطاء</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.student.full_name)}</td><td>${esc(categoryName(x.student))}</td><td>${esc(studentTrackAr[x.student.track_code]||'—')}</td><td>${fmt(x.stats.hifz_pages)}</td><td>${fmt(x.stats.review_pages)}</td><td>${fmt(x.stats.sard_pages)}</td><td>${x.stats.present_days||0}</td><td>${x.stats.absent_days||0}</td><td>${x.stats.excused_days||0}</td><td>${x.stats.late_days||0}</td><td>${x.stats.mistakes||0}</td></tr>`).join('')}</tbody></table></div>${reportFooterHtml()}</div>`}
function dailyReportHtml(){let rows=state.dailySummary;let sum=k=>rows.reduce((a,x)=>a+Number(x[k]||0),0);return `<div class="report-paper">${reportHeaderHtml('التقرير اليومي للجلسات',new Date().toLocaleDateString('ar-EG-u-nu-latn'))}<div class="report-summary"><div><b>${rows.length}</b>طالب مسجل</div><div><b>${fmt(sum('hifz_pages'))}</b>حفظ</div><div><b>${fmt(sum('review_pages'))}</b>مراجعة</div><div><b>${fmt(sum('sard_pages'))}</b>سرد</div></div>${rows.length?`<div style="overflow:auto"><table class="report-table"><thead><tr><th>#</th><th>الطالب</th><th>الحضور</th><th>الحفظ</th><th>المراجعة</th><th>السرد</th><th>الأخطاء</th><th>السلوك</th><th>تعليق المحفّظ</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.full_name)}</td><td>${attAr[r.attendance_status]||'—'}</td><td>${fmt(r.hifz_pages)}</td><td>${fmt(r.review_pages)}</td><td>${fmt(r.sard_pages)}</td><td>${r.mistakes||0}</td><td>${behAr[r.behavior]||'—'}</td><td>${esc(r.teacher_comment||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">لا توجد تقارير يومية مسجلة لهذا اليوم.</div>'}${reportFooterHtml()}</div>`}
function reportsPage(){let tabs=`<div class="seg"><button class="${state.reportTab==='daily'?'active':''}" onclick="setReportTab('daily')">اليومي</button><button class="${state.reportTab==='monthly'?'active':''}" onclick="setReportTab('monthly')">الشهري</button></div>`,tools=`<div class="actions report-tools" style="margin:12px 0"><button class="mini" onclick="exportReportsExcel()">Excel</button><button class="mini" onclick="exportCurrentReportWord()">Word منسق</button><button class="mini" onclick="printCurrentReport()">PDF / طباعة</button><button class="mini" onclick="exportCurrentReportImage()">صورة PNG</button></div>`;return `${tabs}${tools}<div id="reportExportArea">${state.reportTab==='daily'?dailyReportHtml():monthlyReportHtml()}</div>`}
function setReportTab(t){state.reportTab=t;render()}
function dailyReportCards(){if(!state.dailySummary.length)return '<div class="empty">لم تُسجل تقارير اليوم بعد.</div>';return state.dailySummary.map(r=>`<div class="card"><div class="row"><div class="grow"><b>${r.full_name}</b><div class="muted">${attAr[r.attendance_status]||'لم يسجل'} · السلوك ${behAr[r.behavior]||'—'}</div></div><span class="badge">${fmt(r.hifz_pages)} ص حفظ</span></div><div class="grid stats">${stat('الحفظ',fmt(r.hifz_pages)+' ص')}${stat('المراجعة',fmt(r.review_pages)+' ص')}${stat('السرد',fmt(r.sard_pages)+' ص')}${stat('الأخطاء',r.mistakes||0)}</div>${r.teacher_comment?`<div class="notice">${r.teacher_comment}</div>`:''}</div>`).join('')}


function guardianPeriodBounds(){let mode=state.guardianPeriodMode||'month';if(mode==='day'){let d=/^\d{4}-\d{2}-\d{2}$/.test(String(state.guardianPeriodDay||''))?state.guardianPeriodDay:today();return {from:d,to:d}}if(mode==='month'){let ym=/^\d{4}-\d{2}$/.test(String(state.guardianPeriodMonth||''))?state.guardianPeriodMonth:today().slice(0,7);return {from:ym+'-01',to:monthEnd(ym)}}let from=/^\d{4}-\d{2}-\d{2}$/.test(String(state.guardianPeriodFrom||''))?state.guardianPeriodFrom:monthStart(),to=/^\d{4}-\d{2}-\d{2}$/.test(String(state.guardianPeriodTo||''))?state.guardianPeriodTo:today();return {from,to}}
function guardianDateLabel(d,monthOnly=false){if(!d)return '—';try{let x=new Date((monthOnly?d+'-01':d)+'T00:00:00');return new Intl.DateTimeFormat('ar-EG-u-nu-latn',{day:monthOnly?undefined:'numeric',month:'long',year:'numeric'}).format(x)}catch{return d}}
function guardianPeriodLabel(){let b=guardianPeriodBounds();if(state.guardianPeriodMode==='day')return guardianDateLabel(b.from);if(state.guardianPeriodMode==='month')return guardianDateLabel(String(state.guardianPeriodMonth||today().slice(0,7)),true);return `${guardianDateLabel(b.from)} — ${guardianDateLabel(b.to)}`}
function guardianPeriodKey(){let b=guardianPeriodBounds();return `${b.from}:${b.to}`}
function guardianPeriodValid(){let b=guardianPeriodBounds();return /^\d{4}-\d{2}-\d{2}$/.test(b.from)&&/^\d{4}-\d{2}-\d{2}$/.test(b.to)&&b.from<=b.to}
function guardianVisibleChildren(){let rows=activeStudents();if(state.guardianChildFilter&&state.guardianChildFilter!=='all')rows=rows.filter(x=>x.id===state.guardianChildFilter);return rows}
function guardianChildFilterHtml(){let rows=activeStudents();if(rows.length<2)return '';return `<label class="field guardian-child-filter"><span>الطالب</span><select onchange="setGuardianChildFilter(this.value)"><option value="all">كل أبنائي</option>${rows.map(st=>`<option value="${st.id}" ${state.guardianChildFilter===st.id?'selected':''}>${esc(st.full_name)}</option>`).join('')}</select></label>`}
function guardianPeriodControls(){let mode=state.guardianPeriodMode||'month',dates=mode==='day'?`<label class="field"><span>اليوم</span><input class="input" type="date" value="${esc(state.guardianPeriodDay||today())}" onchange="setGuardianPeriodValue('guardianPeriodDay',this.value)"></label>`:mode==='month'?`<label class="field"><span>الشهر</span><input class="input" type="month" value="${esc(state.guardianPeriodMonth||today().slice(0,7))}" onchange="setGuardianPeriodValue('guardianPeriodMonth',this.value)"></label>`:`<label class="field"><span>من</span><input class="input" type="date" value="${esc(state.guardianPeriodFrom||monthStart())}" onchange="setGuardianPeriodValue('guardianPeriodFrom',this.value)"></label><label class="field"><span>إلى</span><input class="input" type="date" value="${esc(state.guardianPeriodTo||today())}" onchange="setGuardianPeriodValue('guardianPeriodTo',this.value)"></label>`;return `<div class="report-control-card guardian-period-card"><div class="report-period-tabs"><button class="${mode==='day'?'active':''}" onclick="setGuardianPeriodMode('day')">يوم معين</button><button class="${mode==='range'?'active':''}" onclick="setGuardianPeriodMode('range')">فترة</button><button class="${mode==='month'?'active':''}" onclick="setGuardianPeriodMode('month')">شهر معين</button></div><div class="guardian-period-grid">${dates}${guardianChildFilterHtml()}</div><div class="guardian-period-summary"><span>الفترة المعروضة</span><b>${esc(guardianPeriodLabel())}</b></div>${guardianAnalyticsStatusHtml()}</div>`}
function guardianAnalyticsStatusHtml(){if(state.guardianAnalyticsError)return `<div class="notice red guardian-analytics-note">تعذر تحديث النتائج: ${esc(state.guardianAnalyticsError)}</div>`;if((state.offline||!state.networkVerified)&&state.guardianAnalyticsUpdatedAt){let d=new Date(state.guardianAnalyticsUpdatedAt);return `<div class="notice guardian-analytics-note">هذه آخر نتائج محفوظة على الجهاز · آخر تحديث ${esc(d.toLocaleString('ar-EG-u-nu-latn'))}</div>`}return ''}
async function setGuardianPeriodMode(mode){if(!['day','range','month'].includes(mode))return;state.guardianPeriodMode=mode;if(mode==='day'&&!state.guardianPeriodDay)state.guardianPeriodDay=today();if(mode==='month'&&!state.guardianPeriodMonth)state.guardianPeriodMonth=today().slice(0,7);if(mode==='range'){if(!state.guardianPeriodFrom)state.guardianPeriodFrom=monthStart();if(!state.guardianPeriodTo)state.guardianPeriodTo=today()}state.guardianAnalyticsError='';await render()}
async function setGuardianPeriodValue(field,value){state[field]=value;if(!guardianPeriodValid()){state.guardianAnalyticsError='تاريخ البداية يجب أن يكون قبل تاريخ النهاية أو مساوياً له.';render();return}state.guardianAnalyticsError='';await render()}
async function setGuardianChildFilter(v){state.guardianChildFilter=v||'all';state.guardianAnalyticsError='';await render()}
function competitionKey(studentId,scope,track=state.competitionTrack){return `${studentId}:${scope}:${track}:${guardianPeriodKey()}`}
async function ensureGuardianCompetition(){if(state.profile?.role!=='guardian'||!state.networkVerified||!guardianPeriodValid())return;let children=guardianVisibleChildren(),b=guardianPeriodBounds(),jobs=[];state.guardianAnalyticsError='';for(let st of children){for(let scope of ['center','category']){let k=competitionKey(st.id,scope);if(state.guardianCompetition[k]!==undefined)continue;jobs.push((async()=>{let r=await db.rpc('guardian_competition_board_range',{p_student_id:st.id,p_track:state.competitionTrack,p_scope:scope,p_from:b.from,p_to:b.to});if(r.error){state.guardianAnalyticsError=r.error.message||'تعذر تحميل المنافسة';state.guardianCompetition[k]=[]}else state.guardianCompetition[k]=r.data||[]})())}}if(jobs.length){await Promise.all(jobs);if(!state.guardianAnalyticsError)state.guardianAnalyticsUpdatedAt=new Date().toISOString();cacheSnapshot()}}
function competitionRows(st,scope){return state.guardianCompetition[competitionKey(st.id,scope)]||[]}
function competitionActivity(rows){return rows.some(x=>Number(x.pages||0)>0||Number(x.points||0)>0)}
function competitionMyRow(rows){return rows.find(x=>x.is_my_child)||null}
function competitionBoardRows(rows,st){let has=competitionActivity(rows);if(!has)return `<div class="comp-empty">لا توجد تسميعات ${esc(trackAr[state.competitionTrack]||'')} لـ${st?` ${esc(st.full_name)}`:''} خلال ${esc(guardianPeriodLabel())}.</div>`;return `<div class="comp-list">${rows.map(x=>`<div class="comp-row ${x.is_my_child?'mine':''}"><div class="comp-rank">${x.rank_no}</div><div class="comp-name"><b>${esc(x.full_name)}${x.is_my_child?'<span class="comp-you">ابني</span>':''}</b><span>${esc(x.category_name||x.halaqa_name||'طالب بالمركز')}</span></div><div class="comp-score"><b>${fmt(x.pages)} ص</b><span>${fmt(x.points)} نقطة</span></div></div>`).join('')}</div>`}
function competitionScopeCard(st,scope){let rows=competitionRows(st,scope),mine=competitionMyRow(rows),has=competitionActivity(rows),isCat=scope==='category',cat=categoryName(st);if(isCat&&!st.category_id)return `<div class="comp-scope-card"><div class="comp-title"><h3>ترتيب الفئة</h3><span class="badge">غير محددة</span></div><div class="comp-empty">هذا الطالب غير موضوع في فئة بعد. حدّد فئته من ملف الطالب ليظهر ترتيبه مقارنة بطلاب نفس الفئة.</div></div>`;let total=mine?.total_students||rows[0]?.total_students||0,avg=mine?.avg_pages??rows[0]?.avg_pages??0,rank=has&&mine?mine.rank_no:'—',pages=mine?.pages||0,title=isCat?`ترتيب الفئة · ${esc(cat)}`:'الترتيب على المركز';return `<div class="comp-scope-card"><div class="comp-title"><h3>${title}</h3><span class="badge">${esc(guardianPeriodLabel())}</span></div><div class="comp-summary"><div class="box"><span>ترتيب ابني</span><b>${rank}${rank!=='—'?` / ${total}`:''}</b></div><div class="box"><span>صفحات ابني</span><b>${fmt(pages)}</b></div><div class="box"><span>متوسط المجموعة</span><b>${fmt(avg)} ص</b></div></div><div class="muted" style="margin:8px 0">نعرض أعلى الطلاب، ومعهم الطلاب الأقرب لترتيب ابنك قبله وبعده.</div>${competitionBoardRows(rows,st)}</div>`}
function guardianCompetitionPage(){let children=guardianVisibleChildren();return `${offlineNotice()}<div class="hero"><h2>إحصائيات ومنافسة أبنائي</h2><p>مقارنة تحفيزية بالصفحات والنقاط فقط، مع الحفاظ على خصوصية الملفات الشخصية.</p><div class="comp-hero-note">اختر يوماً أو فترة أو شهراً، ثم تابع ترتيب ابنك داخل فئته وعلى مستوى المركز.</div></div>${guardianPeriodControls()}<div class="tabs"><button class="tab ${state.competitionTrack==='hifz'?'active':''}" onclick="setCompetitionTrack('hifz')">الحفظ</button><button class="tab ${state.competitionTrack==='review'?'active':''}" onclick="setCompetitionTrack('review')">المراجعة</button><button class="tab ${state.competitionTrack==='sard'?'active':''}" onclick="setCompetitionTrack('sard')">السرد</button></div>${children.map(st=>`<div class="section-head"><h3>${esc(st.full_name)}</h3><button class="mini" onclick="studentProfile('${st.id}')">ملف ابني</button></div>${competitionScopeCard(st,'category')}${competitionScopeCard(st,'center')}`).join('')||'<div class="empty">لا يوجد طالب مربوط بهذا الحساب.</div>'}<div class="comp-privacy">تظهر هنا أسماء الطلاب وترتيبهم وعدد الصفحات والنقاط فقط لأغراض التحفيز. لا يمكن لولي الأمر فتح ملفات الطلاب الآخرين أو رؤية الهوية أو تاريخ الميلاد أو الملاحظات والتقارير الخاصة بهم.</div>`}
async function setCompetitionTrack(t){state.competitionTrack=t;state.guardianAnalyticsError='';await render()}
function guardianRangeRankKey(studentId){return `${studentId}:${guardianPeriodKey()}`}
async function ensureGuardianRangeRanks(){if(state.profile?.role!=='guardian'||!state.networkVerified||!guardianPeriodValid())return;state.guardianRangeDashboards=state.guardianRangeDashboards||{};let children=guardianVisibleChildren(),b=guardianPeriodBounds(),jobs=[];state.guardianAnalyticsError='';for(let st of children){let k=guardianRangeRankKey(st.id);if(state.guardianRangeDashboards[k]!==undefined)continue;jobs.push((async()=>{let r=await db.rpc('guardian_student_dashboard_range',{p_student_id:st.id,p_from:b.from,p_to:b.to});if(r.error){state.guardianAnalyticsError=r.error.message||'تعذر تحميل الترتيب';state.guardianRangeDashboards[k]={};state.guardianRangeRanks[k]=[]}else{state.guardianRangeDashboards[k]=r.data||{};let ranks=r.data?.ranks||{};state.guardianRangeRanks[k]=['hifz','review','sard'].map(track=>({track,rank_no:ranks[track]?.halaqa_rank??null,total_students:ranks[track]?.halaqa_total??0,points:ranks[track]?.points??0,pages:ranks[track]?.pages??0}))}})())}if(jobs.length){await Promise.all(jobs);if(!state.guardianAnalyticsError)state.guardianAnalyticsUpdatedAt=new Date().toISOString();cacheSnapshot()}}
function guardianRangeRankRow(studentId,track){return (state.guardianRangeRanks[guardianRangeRankKey(studentId)]||[]).find(x=>x.track===track)||null}
function guardianRangeRankTiles(st){let k=guardianRangeRankKey(st.id),dash=state.guardianRangeDashboards?.[k]||{},ranks=dash.ranks||{};return `<div class="guardian-rank-stack">${['hifz','review','sard'].map(t=>{let x=ranks[t]||guardianRangeRankRow(st.id,t)||{},has=Number(x.pages||0)>0||Number(x.points||0)>0,hr=Number((x.halaqa_rank??x.rank_no) || 0),ht=Number((x.halaqa_total??x.total_students) || 0),cr=Number(x.category_rank||0),ct=Number(x.category_total||0);return `<div class="guardian-rank-line"><div><b>${trackAr[t]}</b><small>${has?`${fmt(x.points)} نقطة · ${fmt(x.pages)} ص`:'لا توجد تسميعات خلال الفترة'}</small></div><span><small>الفئة</small><b>${has&&cr&&ct?`${cr} / ${ct}`:'—'}</b></span><span><small>الحلقة</small><b>${has&&hr&&ht?`${hr} / ${ht}`:'—'}</b></span></div>`}).join('')}</div>`}
function guardianRankingPage(){let children=guardianVisibleChildren();return `${offlineNotice()}<div class="hero"><h2>ترتيب أبنائي</h2><p>يظهر ترتيب ابنك داخل الحلقة دون كشف نتائج أو ملفات الطلاب الآخرين.</p><div class="comp-hero-note">يمكنك الآن اختيار يوم معين أو فترة كاملة أو شهر سابق.</div></div>${guardianPeriodControls()}${children.map(st=>`<div class="card"><div class="row">${avatarHtml(st)}<div class="grow"><b>${esc(st.full_name)}</b><div class="muted">ترتيبه داخل فئته وعلى الحلقة ضمن نفس المسار · ${esc(guardianPeriodLabel())}</div></div></div>${guardianRangeRankTiles(st)}</div>`).join('')||'<div class="empty">لا يوجد طالب مربوط بالحساب.</div>'}<div class="privacy-note">لا يعرض هذا القسم نقاط أو تقارير الطلاب الآخرين. تُستخدم نتائج الحلقة في الخادم لحساب ترتيب ابنك فقط.</div>`}

function rankingPage(){if(state.profile?.role==='guardian')return guardianRankingPage();let periodRows=state.rankPeriod==='day'?state.leaderDaily:state.leaderMonthly;let rows=periodRows.filter(x=>x.track===state.rankTrack).sort((a,b)=>Number(b.points||0)-Number(a.points||0)||Number(b.pages||0)-Number(a.pages||0)||Number(a.penalty_per_page??999)-Number(b.penalty_per_page??999));return `<div class="hero"><h2>الترتيب والإحصائيات</h2><p>ترتيب مستقل للحفظ والمراجعة والسرد؛ النقاط قريبة من عدد الصفحات وليست بالمئات.</p></div><div class="card"><b>معيار جودة التسميع V6</b><div class="muted">نسبة السلامة مخصّصة لتحديد التقييم فقط (ممتاز/جيد جداً/جيد/يحتاج إعادة). أمّا ترتيب الطلاب فيبقى بنظام النقاط المعتاد؛ الخطأ والنقرة يؤثران في النقاط كما في النظام السابق.</div><div class="score-explain"><div class="ex">ممتاز<br>90%–100%</div><div class="vg">جيد جداً<br>80%–&lt;90%</div><div class="gd">جيد<br>70%–&lt;80%</div><div class="rp">يحتاج إعادة<br>&lt; 70%</div></div></div><div class="seg" style="margin-top:13px"><button class="${state.rankPeriod==='day'?'active':''}" onclick="setRankPeriod('day')">اليوم</button><button class="${state.rankPeriod==='month'?'active':''}" onclick="setRankPeriod('month')">الشهر</button></div><div class="tabs" style="margin-top:12px"><button class="tab ${state.rankTrack==='hifz'?'active':''}" onclick="setRankTrack('hifz')">الحفظ</button><button class="tab ${state.rankTrack==='review'?'active':''}" onclick="setRankTrack('review')">المراجعة</button><button class="tab ${state.rankTrack==='sard'?'active':''}" onclick="setRankTrack('sard')">السرد</button></div><div class="section-head"><h3>ترتيب ${trackAr[state.rankTrack]}</h3></div>${rows.map((x,i)=>`<div class="card rank-row track-${state.rankTrack}"><div class="rank">${i+1}</div><div class="grow"><b>${esc(x.full_name)}</b><div class="muted">${fmt(x.pages)} صفحة · ${x.mistakes||0} أخطاء · ${x.prompts||0} نقرات · ${fmt(x.penalty_per_page)} خصم/صفحة</div></div><div style="text-align:left"><b>${fmt(x.points)}</b><div class="muted">نقطة</div></div></div>`).join('')||'<div class="empty">لا توجد بيانات ترتيب بعد.</div>'}<div class="notice">عند تساوي النقاط: يُفضّل صاحب الصفحات الأكثر، ثم الأقل في الخصم لكل صفحة.</div>`}
function setRankTrack(t){state.rankTrack=t;render()}function setRankPeriod(p){state.rankPeriod=p;render()}

function toAsciiDigits(value=''){return String(value).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))}
function normalizeQuranNumberInput(el){if(!el)return null;el.value=toAsciiDigits(el.value).replace(/\D/g,'');return el.value===''?null:Number(el.value)}
function quranNumberValue(prefix,suffix,fallback=0){let el=$('#'+prefix+suffix);if(!el)return fallback;let n=normalizeQuranNumberInput(el);return n==null?fallback:n}
function quranPage(){return `<div class="hero"><h2>حاسبة القرآن</h2><p>مصحف المدينة 604 صفحات · 114 سورة · اختيار الجزء أو السور المتفرقة أو الصفحة مع آيات البداية والنهاية.</p></div><div class="card"><div class="seg"><button class="active" onclick="switchQTab(this,'ayahs')">السورة والآية</button><button onclick="switchQTab(this,'pages')">الصفحات</button><button onclick="switchQTab(this,'surahs')">سور متعددة</button><button onclick="switchQTab(this,'juz')">الأجزاء</button></div><div id="qAyahs" class="mode-panel">${qAyahPanel('qc')}</div><div id="qPages" class="mode-panel hidden">${qPagesPanel('qc')}</div><div id="qSurahs" class="mode-panel hidden">${qSurahsPanel('qc')}</div><div id="qJuz" class="mode-panel hidden">${qJuzPanel('qc')}</div><div id="qResult" class="qcalc-result"><span class="muted">المقدار المحسوب</span><div><strong>0</strong> صفحة</div></div></div><div class="notice"><b>حساب محلي دون إنترنت:</b> نطاقات الآيات والسور والأجزاء تُحسب وفق مواضع الآيات على سطور مصحف المدينة QCF4 (15 سطراً للصفحة)، وليس بنسبة عدد الآيات. اختيار صفحات كاملة يبقى عدّاً مباشراً.</div>`}
function switchQTab(btn,t){btn.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');['Ayahs','Pages','Surahs','Juz'].forEach(x=>$('#q'+x)?.classList.add('hidden'));$('#q'+t[0].toUpperCase()+t.slice(1))?.classList.remove('hidden')}
function juzButtons(prefix,multi=false){return `<div class="juz-grid">${juzStarts.map((_,i)=>`<button id="${prefix}J${i+1}" type="button" class="juz-chip" onclick="${multi?`toggleJuzSelection('${prefix}',${i+1})`:`pickJuz('${prefix}',${i+1})`}">${i+1}</button>`).join('')}</div>`}
function quranJuzGlobalRange(j){let n=Math.max(1,Math.min(30,Number(j)||1)),start=globalAyah(...juzStarts[n-1]),end=n<30?globalAyah(...juzStarts[n])-1:6236;return {start,end}}
function quranSurahsForJuz(j){let r=quranJuzGlobalRange(j),out=[];for(let s=1;s<=114;s++){let a=globalAyah(s,1),b=globalAyah(s,ayahCounts[s-1]);if(a<=r.end&&b>=r.start)out.push(s)}return out}
function quranJuzForAyah(surah,ayah){let g=globalAyah(Number(surah)||1,Number(ayah)||1);for(let j=30;j>=1;j--){let r=quranJuzGlobalRange(j);if(g>=r.start&&g<=r.end)return j}return 1}
function ayahPickerSurahButtons(prefix,j,selected){return quranSurahsForJuz(j).map(s=>`<button id="${prefix}AS${s}" class="ayah-surah-chip ${Number(selected)===s?'active':''}" type="button" onclick="selectAyahPickerSurah('${prefix}',${s})">${s}. ${esc(surahs[s-1])}</button>`).join('')}
function qAyahPanel(prefix,row=false){let defaultJuz=30,defaultSurah=quranSurahsForJuz(defaultJuz)[0]||78,max=ayahCounts[defaultSurah-1];return `<div class="ayah-picker" data-prefix="${prefix}"><div class="ayah-picker-label">الجزء</div><div class="ayah-juz-strip">${Array.from({length:30},(_,i)=>`<button id="${prefix}AJ${i+1}" class="ayah-juz-chip ${i+1===defaultJuz?'active':''}" type="button" onclick="selectAyahPickerJuz('${prefix}',${i+1})">${i+1}</button>`).join('')}</div><div class="muted ayah-picker-help">اختر الجزء لفلترة السور. إذا كانت السورة موزعة على جزئين فستظهر كاملة في كليهما.</div><div class="ayah-picker-label">السورة</div><div id="${prefix}AyahSurahStrip" class="ayah-surah-strip">${ayahPickerSurahButtons(prefix,defaultJuz,defaultSurah)}</div><input id="${prefix}SS" type="hidden" value="${defaultSurah}"><input id="${prefix}ES" type="hidden" value="${defaultSurah}"><div class="ayah-picker-label">الآيات</div><div class="ayah-range-numbers"><label><span>من آية</span><input id="${prefix}SA" class="input" type="text" inputmode="numeric" pattern="[0-9]*" dir="ltr" value="1" data-min="1" data-max="${max}" oninput="normalizeQuranNumberInput(this);syncAyahPickerRange('${prefix}','start',this.value)"></label><label><span>إلى آية</span><input id="${prefix}EA" class="input" type="text" inputmode="numeric" pattern="[0-9]*" dir="ltr" value="${max}" data-min="1" data-max="${max}" oninput="normalizeQuranNumberInput(this);syncAyahPickerRange('${prefix}','end',this.value)"></label></div><div class="ayah-dual-range" style="--start:0%;--end:100%"><div class="ayah-range-fill"></div><input id="${prefix}SARange" type="range" min="1" max="${max}" value="1" oninput="syncAyahPickerRange('${prefix}','start',this.value)"><input id="${prefix}EARange" type="range" min="1" max="${max}" value="${max}" oninput="syncAyahPickerRange('${prefix}','end',this.value)"></div><div id="${prefix}AyahPickerSummary" class="selection-summary">${esc(surahs[defaultSurah-1])}: من آية 1 إلى آية ${max}</div></div>${!row?`<button class="btn btn-primary" type="button" onclick="calcStandaloneAyahs('${prefix}')">احسب الصفحات والآيات</button>`:''}`}
function selectAyahPickerJuz(prefix,j){let current=Number($('#'+prefix+'SS')?.value)||0,available=quranSurahsForJuz(j);$$('.ayah-juz-chip').filter(b=>b.id?.startsWith(prefix+'AJ')).forEach(b=>b.classList.toggle('active',b.id===prefix+'AJ'+j));let box=$('#'+prefix+'AyahSurahStrip');if(box)box.innerHTML=ayahPickerSurahButtons(prefix,j,available.includes(current)?current:available[0]);if(!available.includes(current)&&available[0])selectAyahPickerSurah(prefix,available[0],{keepJuz:true});else if(current)selectAyahPickerSurah(prefix,current,{keepRange:true,keepJuz:true})}
function selectAyahPickerSurah(prefix,surah,{keepRange=false,keepJuz=false}={}){let s=Math.max(1,Math.min(114,Number(surah)||1)),max=ayahCounts[s-1],sa=$('#'+prefix+'SA'),ea=$('#'+prefix+'EA'),sr=$('#'+prefix+'SARange'),er=$('#'+prefix+'EARange');if($('#'+prefix+'SS'))$('#'+prefix+'SS').value=String(s);if($('#'+prefix+'ES'))$('#'+prefix+'ES').value=String(s);$$('.ayah-surah-chip').filter(b=>b.id?.startsWith(prefix+'AS')).forEach(b=>b.classList.toggle('active',b.id===prefix+'AS'+s));for(let el of [sa,ea,sr,er])if(el){el.max=String(max);if(el.dataset)el.dataset.max=String(max)};let start=keepRange?Math.min(max,Math.max(1,Number(sa?.value)||1)):1,end=keepRange?Math.min(max,Math.max(start,Number(ea?.value)||max)):max;if(sa)sa.value=String(start);if(ea)ea.value=String(end);if(sr)sr.value=String(start);if(er)er.value=String(end);if(!keepJuz){let j=quranJuzForAyah(s,start);selectAyahPickerJuzVisual(prefix,j)}updateAyahPickerRangeVisual(prefix);scheduleAyahPickerCalc(prefix)}
function selectAyahPickerJuzVisual(prefix,j){$$('.ayah-juz-chip').filter(b=>b.id?.startsWith(prefix+'AJ')).forEach(b=>b.classList.toggle('active',b.id===prefix+'AJ'+j))}
function syncAyahPickerRange(prefix,side,value){let s=Number($('#'+prefix+'SS')?.value)||1,max=ayahCounts[s-1],sa=$('#'+prefix+'SA'),ea=$('#'+prefix+'EA'),sr=$('#'+prefix+'SARange'),er=$('#'+prefix+'EARange'),ascii=toAsciiDigits(value).replace(/\D/g,''),v=Math.min(max,Math.max(1,Math.round(Number(ascii)||1)));let start=Number(sa?.value)||1,end=Number(ea?.value)||max;if(side==='start'){start=v;if(start>end)end=start}else{end=v;if(end<start)start=end}if(sa)sa.value=String(start);if(ea)ea.value=String(end);if(sr)sr.value=String(start);if(er)er.value=String(end);updateAyahPickerRangeVisual(prefix);scheduleAyahPickerCalc(prefix)}
function updateAyahPickerRangeVisual(prefix){let s=Number($('#'+prefix+'SS')?.value)||1,max=ayahCounts[s-1],start=Number($('#'+prefix+'SA')?.value)||1,end=Number($('#'+prefix+'EA')?.value)||max,box=$('#'+prefix+'AyahPickerSummary'),wrap=$('#'+prefix+'SARange')?.closest('.ayah-dual-range');if(box)box.textContent=`${surahs[s-1]}: من آية ${start} إلى آية ${end} · ${end-start+1} آية`;if(wrap){let den=Math.max(1,max-1),a=(start-1)/den*100,b=(end-1)/den*100;wrap.style.setProperty('--start',a+'%');wrap.style.setProperty('--end',b+'%')}}
function scheduleAyahPickerCalc(prefix){clearTimeout(window.__halaqatiAyahPickerTimer?.[prefix]);window.__halaqatiAyahPickerTimer ||= {};window.__halaqatiAyahPickerTimer[prefix]=setTimeout(()=>{let row=document.querySelector(`.rec-row[data-id="${prefix}"]`);if(row&&row.dataset.mode==='ayahs')calcRecRow(row);else if(prefix==='qc'&&$('#qResult'))calcStandaloneAyahs(prefix).catch?.(()=>{})},120)}
function syncAyahPickerFromFields(prefix){let s=Number($('#'+prefix+'SS')?.value)||78,start=Number($('#'+prefix+'SA')?.value)||1,end=Number($('#'+prefix+'EA')?.value)||start,j=quranJuzForAyah(s,start),box=$('#'+prefix+'AyahSurahStrip');selectAyahPickerJuzVisual(prefix,j);if(box)box.innerHTML=ayahPickerSurahButtons(prefix,j,s);selectAyahPickerSurah(prefix,s,{keepRange:true,keepJuz:true});if($('#'+prefix+'SA'))$('#'+prefix+'SA').value=String(start);if($('#'+prefix+'EA'))$('#'+prefix+'EA').value=String(end);if($('#'+prefix+'SARange'))$('#'+prefix+'SARange').value=String(start);if($('#'+prefix+'EARange'))$('#'+prefix+'EARange').value=String(end);updateAyahPickerRangeVisual(prefix)}
function qPagesPanel(prefix,row=false){return `<div class="range-pair"><label class="field"><span>من صفحة</span><input id="${prefix}PF" class="input" type="text" inputmode="numeric" pattern="[0-9]*" dir="ltr" data-min="1" data-max="604" value="1" oninput="normalizeQuranNumberInput(this)"></label><label class="field"><span>إلى صفحة</span><input id="${prefix}PT" class="input" type="text" inputmode="numeric" pattern="[0-9]*" dir="ltr" data-min="1" data-max="604" value="1" oninput="normalizeQuranNumberInput(this)"></label></div><div class="actions"><button class="btn btn-soft" type="button" onclick="previewPages('${prefix}')">عرض سور وآيات طرفي النطاق</button>${!row?`<button class="btn btn-primary" type="button" onclick="calcStandalonePages('${prefix}')">احسب</button>`:''}</div><div id="${prefix}PagePreview" class="page-preview"></div>`}
function qSurahsPanel(prefix,row=false){return `<div class="muted">يمكن اختيار سور غير متجاورة؛ اضغط السورة لإضافتها أو إزالتها.</div><div id="${prefix}SurahGrid" class="surah-select-grid">${surahs.map((x,i)=>`<button id="${prefix}Surah${i+1}" type="button" onclick="toggleSurahSelection('${prefix}',${i+1})">${i+1}. ${x}</button>`).join('')}</div><div id="${prefix}SurahSummary" class="selection-summary">لم يتم اختيار سور.</div>${!row?`<button class="btn btn-primary" type="button" onclick="calcStandaloneMultiSurahs('${prefix}')">احسب السور المختارة</button>`:''}`}
function qJuzPanel(prefix,row=false){return `<div class="muted">اختر جزءاً أو أكثر؛ يمكن اختيار أجزاء غير متجاورة.</div>${juzButtons(prefix,true)}<div id="${prefix}JuzSummary" class="selection-summary">لم يتم اختيار أجزاء.</div>${!row?`<button class="btn btn-primary" type="button" onclick="calcStandaloneJuz('${prefix}')">احسب الأجزاء المختارة</button>`:''}`}
function surahAyahFromGlobal(g){let s=1;while(s<=114&&ayahPrefix[s]<g)s++;return [s,g-ayahPrefix[s-1]]}
function pickJuz(prefix,j){let start=juzStarts[j-1],end;if(j<30){let ng=globalAyah(...juzStarts[j]);end=surahAyahFromGlobal(ng-1)}else end=[114,ayahCounts[113]];$('#'+prefix+'SS').value=start[0];$('#'+prefix+'SA').value=start[1];$('#'+prefix+'ES').value=end[0];$('#'+prefix+'EA').value=end[1];$$('.juz-chip').filter(b=>b.id?.startsWith(prefix+'J')).forEach(b=>b.classList.remove('active'));$('#'+prefix+'J'+j)?.classList.add('active');toast(`تم تحديد الجزء ${j} كاملاً`)}
function selectedNums(prefix,kind){let base=kind==='surah'?'Surah':'J';return $$(`button[id^="${prefix}${base}"]`).filter(b=>b.classList.contains('active')).map(b=>Number(b.id.replace(prefix+base,'')))}
function toggleSurahSelection(prefix,n){$('#'+prefix+'Surah'+n).classList.toggle('active');let arr=selectedNums(prefix,'surah');$('#'+prefix+'SurahSummary').textContent=arr.length?`المحدد: ${arr.map(x=>surahs[x-1]).join('، ')} · ${arr.length} سورة`:'لم يتم اختيار سور.'}
function toggleJuzSelection(prefix,n){$('#'+prefix+'J'+n).classList.toggle('active');let arr=selectedNums(prefix,'juz');$('#'+prefix+'JuzSummary').textContent=arr.length?`الأجزاء المحددة: ${arr.join('، ')}`:'لم يتم اختيار أجزاء.'}
async function calcStandalonePages(p){let a=Number($('#'+p+'PF').value),b=Number($('#'+p+'PT').value);if(!a||!b||b<a)return toast('تحقق من الصفحات');let sel=standalonePageSelections[p];if(sel?.start&&sel?.end){let d=await calculateAyahRangeData(sel.start.surah,sel.start.ayah,sel.end.surah,sel.end.ayah);showQResult(d.pages,`${d.ayahs} آية · تحديد جزئي من ص ${a} إلى ص ${b}`)}else showQResult(b-a+1,`صفحات كاملة من ${a} إلى ${b}`)}
async function calcStandaloneAyahs(p){let d=await calculateAyahRangeData(+$('#'+p+'SS').value,+$('#'+p+'SA').value,+$('#'+p+'ES').value,+$('#'+p+'EA').value);showQResult(d.pages,`${d.ayahs} آية · من صفحة ${d.startPage} إلى ${d.endPage}`)}
async function calcStandaloneMultiSurahs(p){let arr=selectedNums(p,'surah');if(!arr.length)return toast('اختر سورة واحدة على الأقل');let d=await calculateFullSurahs(arr);showQResult(d.pages,`${arr.length} سورة · ${d.ayahs} آية`)}
async function calcStandaloneJuz(p){let arr=selectedNums(p,'juz');if(!arr.length)return toast('اختر جزءاً واحداً على الأقل');let d=await calculateJuzs(arr);showQResult(d.pages,`${arr.length} جزء · ${d.ayahs} آية`)}
function showQResult(pages,detail=''){$('#qResult').innerHTML=`<span class="muted">المقدار المحسوب</span><div><strong>${fmt(pages)}</strong> صفحة</div><div class="muted">${esc(detail)}</div>`}
const standalonePageSelections={};
async function previewPages(prefix){let a=+$('#'+prefix+'PF').value,b=+$('#'+prefix+'PT').value;if(!a||!b||a<1||b>604||b<a)return toast('تحقق من الصفحات');let box=$('#'+prefix+'PagePreview');if(!(await internetReachable())){box.innerHTML='<div class="notice">الحساب الدقيق يعمل دون إنترنت، لكن عرض نص آيات الصفحة يحتاج اتصالاً.</div>';return}box.innerHTML='<div class="muted">جاري تحميل آيات الصفحة...</div>';try{let pages=[a,b],data=await Promise.all(pages.map(x=>apiGet(`https://api.alquran.cloud/v1/page/${x}/quran-uthmani-quran-academy`)));box.innerHTML=data.map((d,i)=>pageEndpointCard(prefix,pages[i],d.ayahs||[],i===0?'start':'end',a===b)).join('')}catch(e){box.innerHTML=`<div class="notice">${esc(e.message)}</div>`}}
function pageEndpointCard(prefix,page,ayahs,side,same){let label=side==='start'?'بداية التسميع':'نهاية التسميع';if(same&&side==='start')label='اختر آية البداية (ثم اضغط آية أخرى كنهاية من نفس الصفحة)';return `<div class="page-card"><h4>صفحة ${page} · ${label}</h4><div class="ayah-list">${ayahs.map(a=>`<button type="button" class="ayah-chip" onclick="selectPageAyah('${prefix}','${side}',${a.number},${a.surah.number},${a.numberInSurah},${page},this)"><span>${esc(a.surah.name||'')} ${a.numberInSurah}</span><span class="ayah-text">${esc(a.text||'')}</span></button>`).join('')}</div></div>`}
function selectPageAyah(prefix,side,global,surah,ayah,page,btn){let row=document.querySelector(`.rec-row[data-id="${prefix}"]`);let obj={global,surah,ayah,page};if(row){row.dataset[side+'Global']=global;row.dataset[side+'Surah']=surah;row.dataset[side+'Ayah']=ayah}else{standalonePageSelections[prefix] ||= {};standalonePageSelections[prefix][side]=obj}let box=$('#'+prefix+'PagePreview');box?.querySelectorAll('.ayah-chip').forEach(x=>x.classList.remove(side==='start'?'active-start':'active-end'));btn.classList.add(side==='start'?'active-start':'active-end');toast(`تم تحديد ${side==='start'?'البداية':'النهاية'}: ${surahs[surah-1]} آية ${ayah}`)}
const QURAN_LAYOUT_CACHE='halaqati_quran_qcf4_layout_v24';
let quranLayout=window.HALAQATI_QURAN_LAYOUT||null;
function loadQuranLayoutCache(){if(quranLayout)return quranLayout;try{quranLayout=JSON.parse(localStorage.getItem(QURAN_LAYOUT_CACHE)||'null')}catch(e){}return quranLayout}
function compactQcf4Verses(obj){
  let page=new Array(6237).fill(0),first=new Array(6237).fill(0),last=new Array(6237).fill(0);
  for(let [key,v] of Object.entries(obj||{})){
    let [ss,aa]=key.split(':').map(Number),g=globalAyah(ss,aa),lines=(v?.lines||[]).map(x=>Number(x.line)).filter(Boolean);
    page[g]=Number(v?.page||0);first[g]=lines.length?Math.min(...lines):0;last[g]=lines.length?Math.max(...lines):first[g]
  }
  return {version:1,source:'QCF4 Hafs · Madinah Mushaf 1441 AH',lineModel:15,page,first,last}
}
async function ensureQuranLayout(background=false){
  if(loadQuranLayoutCache()?.page?.length>6200)return quranLayout;
  if(!navigator.onLine){if(!background)toast('بيانات المصحف الدقيقة غير مخزنة بعد في نسخة HTML. نسخة APK تتضمنها تلقائياً.');return null}
  try{
    let urls=['https://raw.githubusercontent.com/MohamadHajjRabee/quran-qcf4/main/verses.json','https://cdn.jsdelivr.net/gh/MohamadHajjRabee/quran-qcf4@main/verses.json'],obj=null;
    for(let url of urls){try{let ctl=new AbortController(),tm=setTimeout(()=>ctl.abort(),7000),r=await fetch(url,{cache:'force-cache',signal:ctl.signal});clearTimeout(tm);if(r.ok){obj=await r.json();break}}catch(e){}}
    if(!obj)throw new Error('layout unavailable');
    quranLayout=compactQcf4Verses(obj);try{localStorage.setItem(QURAN_LAYOUT_CACHE,JSON.stringify(quranLayout))}catch(e){}
    return quranLayout
  }catch(e){if(!background)toast('تعذر تنزيل بيانات المصحف الدقيقة حالياً');return null}
}
function quranLineSetForRange(gs,ge,layout){let set=new Set(),sp=0,ep=0;for(let g=gs;g<=ge;g++){let p=Number(layout.page[g]||0),a=Number(layout.first[g]||0),b=Number(layout.last[g]||a);if(!p||!a)continue;if(!sp)sp=p;ep=p;for(let line=a;line<=b;line++)set.add(`${p}:${line}`)}return {set,startPage:sp,endPage:ep}}
function layoutRangeData(ss,sa,es,ea,layout){let gs=globalAyah(ss,sa),ge=globalAyah(es,ea),u=quranLineSetForRange(gs,ge,layout),lineModel=Number(layout.lineModel||15);return {pages:Math.round((u.set.size/lineModel)*100)/100,ayahs:ge-gs+1,startPage:u.startPage||'—',endPage:u.endPage||'—',surahs:es-ss+1,preciseLines:true,source:layout.source}}
const apiCache={};async function apiGet(url){if(apiCache[url])return apiCache[url];let r=await fetch(url);if(!r.ok)throw new Error('تعذر الوصول لبيانات المصحف');let j=await r.json();apiCache[url]=j.data;return j.data}
async function calculateAyahRangeData(ss,sa,es,ea){
  if(ss<1||es>114||sa<1||ea<1)throw new Error('نطاق غير صحيح');if(sa>ayahCounts[ss-1]||ea>ayahCounts[es-1])throw new Error('رقم الآية يتجاوز عدد آيات السورة');let gs=globalAyah(ss,sa),ge=globalAyah(es,ea);if(ge<gs)throw new Error('نهاية النطاق قبل بدايته');
  let layout=loadQuranLayoutCache()||await ensureQuranLayout(true);if(layout?.page?.[gs]&&layout?.page?.[ge])return layoutRangeData(ss,sa,es,ea,layout);
  // Page-boundary fallback when running the loose HTML before its first metadata download.
  try{let [sm,em]=await Promise.all([apiGet(`https://api.alquran.cloud/v1/ayah/${gs}`),apiGet(`https://api.alquran.cloud/v1/ayah/${ge}`)]);let sp=sm.page,ep=em.page,pages=Math.max(1/15,ep-sp+1);return {pages:Math.round(pages*100)/100,ayahs:ge-gs+1,startPage:sp,endPage:ep,surahs:es-ss+1,estimated:true}}catch(e){let frac=(ge-gs+1)/6236*604;return {pages:Math.round(frac*100)/100,ayahs:ge-gs+1,startPage:'—',endPage:'—',surahs:es-ss+1,estimated:true}}
}
async function calculateSelectedRanges(ranges){
  let layout=loadQuranLayoutCache()||await ensureQuranLayout(true),all=new Set(),ayahs=0,minP=0,maxP=0;
  if(layout){for(let [ss,sa,es,ea] of ranges){let gs=globalAyah(ss,sa),ge=globalAyah(es,ea),u=quranLineSetForRange(gs,ge,layout);u.set.forEach(x=>all.add(x));ayahs+=ge-gs+1;if(u.startPage&&(!minP||u.startPage<minP))minP=u.startPage;if(u.endPage>maxP)maxP=u.endPage}return {pages:Math.round((all.size/Number(layout.lineModel||15))*100)/100,ayahs,startPage:minP||'—',endPage:maxP||'—',preciseLines:true,source:layout.source}}
  let total={pages:0,ayahs:0};for(let r of ranges){let d=await calculateAyahRangeData(...r);total.pages+=d.pages;total.ayahs+=d.ayahs}total.pages=Math.round(total.pages*100)/100;return total
}
async function calculateFullSurahs(arr){let d=await calculateSelectedRanges(arr.map(n=>[n,1,n,ayahCounts[n-1]]));d.surahs=arr.length;return d}
async function calculateJuzs(arr){let ranges=[];for(let j of arr){let start=juzStarts[j-1],end;if(j<30){let ng=globalAyah(...juzStarts[j]);end=surahAyahFromGlobal(ng-1)}else end=[114,ayahCounts[113]];ranges.push([start[0],start[1],end[0],end[1]])}return calculateSelectedRanges(ranges)}

function supervisionHasActivePlan(student){
  let d=today();
  return (state.smartPlans||[]).some(p=>p.status!=='archived'&&p.halaqa_id===student.halaqa_id&&(!p.start_date||p.start_date<=d)&&(!p.end_date||p.end_date>=d)&&(p.scope_type==='halaqa'||p.scope_type==='category'&&p.category_id===student.category_id||p.scope_type==='student'&&p.student_id===student.id)&&(p.plan_type!=='hifz'||p.scope_type==='student'||!!p.settings?.student_ranges?.[student.id]))
}
function supervisionFollowupRows(){
  let students=activeStudents(),monthSessions=state.sessions.filter(x=>x.session_date>=monthStart()&&x.session_date<=today()&&x.status!=='cancelled'),dailyById=new Map((state.dailySummary||[]).map(x=>[String(x.student_id||x.id||''),x])),sessionRatioByHalaqa=new Map;
  for(let h of state.halaqas){let count=monthSessions.filter(x=>x.halaqa_id===h.id).length;sessionRatioByHalaqa.set(h.id,count)}
  return students.map(student=>{let reasons=[],score=0,daily=dailyById.get(String(student.id)),goal=currentGoalForStudent(student.id),monthly=state.monthly.find(x=>x.student_id===student.id)||{};
    if(daily?.attendance_status==='absent'){reasons.push('غائب اليوم');score+=50}
    if(!supervisionHasActivePlan(student)){reasons.push('لا توجد خطة ذكية فعالة');score+=30}
    if(goal&&Number(goal.target_hifz_pages||0)>0){let held=sessionRatioByHalaqa.get(student.halaqa_id)||0,expectedDays=Math.max(1,Number(goal.expected_session_days||20)),expected=Number(goal.target_hifz_pages||0)*Math.min(1,held/expectedDays),actual=Number(monthly.hifz_pages||0),gap=Math.max(0,expected-actual);if(gap>=.5){reasons.push(`متأخر ${fmt(gap)} ص عن وتيرة الشهر`);score+=Math.min(20,Math.ceil(gap*4))}}
    return {student,reasons,score}
  }).filter(x=>x.reasons.length).sort((a,b)=>b.score-a.score||a.student.full_name.localeCompare(b.student.full_name,'ar')).slice(0,10)
}
function supervisionAction(icon,title,sub,page){return `<button class="supervision-action" onclick="go('${page}')"><span class="supervision-action-icon">${icon}</span><span><b>${title}</b><small>${sub}</small></span><span class="supervision-action-arrow">←</span></button>`}
function supervisionPage(){
  let monthSessions=state.sessions.filter(x=>x.session_date>=monthStart()&&x.session_date<=today()&&x.status!=='cancelled'),active=activeStudents(),withoutPlan=active.filter(x=>!supervisionHasActivePlan(x)).length,absent=(state.dailySummary||[]).filter(x=>x.attendance_status==='absent').length,follow=supervisionFollowupRows();
  return `<div class="hero supervision-hero"><h2>متابعة المحفّظ</h2><p>لوحة تشغيل يومية: تعرف من يحتاج متابعة الآن، ثم تفتح الإجراء المطلوب مباشرة.</p></div>
  <div class="grid stats supervision-stats">${stat('جلسات هذا الشهر',monthSessions.length)}${stat('بلا خطة ذكية',withoutPlan)}${stat('تقارير اليوم',(state.dailySummary||[]).length)}${stat('غياب اليوم',absent)}</div>
  <div class="card supervision-actions-card"><div class="section-head"><h3>اختصارات العمل</h3><span class="badge good">وصول سريع</span></div><div class="supervision-actions-grid">
    ${supervisionAction('🗓️','الجلسات اليومية','فتح الجلسة وتسجيل الحضور والتسميع','sessions')}
    ${supervisionAction('🧭','الخطط الذكية','المقرر والتأخر والتعويض','plans')}
    ${supervisionAction('📊','التقارير','تقارير الحلقة والمسارات','reports')}
    ${supervisionAction('🏆','الترتيب','النقاط والإنجازات','ranking')}
    ${supervisionAction('👥','الطلاب','ملفات الطلاب وتعديل البيانات','students')}
    ${supervisionAction('📣','الإعلانات','التواصل مع أولياء الأمور','community')}
  </div></div>
  <div class="card supervision-follow-card"><div class="section-head"><div><h3>يحتاج متابعة الآن</h3><div class="muted">مرتبة حسب الأولوية التشغيلية</div></div><span class="badge ${follow.length?'warn':'good'}">${follow.length}</span></div>
  ${follow.length?`<div class="supervision-follow-list">${follow.map(x=>`<div class="supervision-follow-row"><div class="avatar">${esc(x.student.full_name?.[0]||'ط')}</div><div class="grow"><b>${esc(x.student.full_name)}</b><div class="supervision-reasons">${x.reasons.map(r=>`<span>${esc(r)}</span>`).join('')}</div></div><button class="mini" onclick="studentProfile('${x.student.id}')">فتح الملف</button></div>`).join('')}</div>`:'<div class="empty supervision-all-good">✅ لا توجد حالات عاجلة في البيانات الحالية.</div>'}
  </div>`
}
function dataPage(){let canImport=canManageStudents(),advanced=roleCanAdmin();return `<div class="hero"><h2>الاستيراد والتصدير</h2><p>تصدير بيانات الطلاب الأساسية واستيراد البيانات مع مرحلة مراجعة قبل الحفظ.</p></div><div class="section-head"><h3>تصدير بيانات الطلاب</h3></div><div class="data-actions"><button class="action-card" onclick="exportStudentsExcel()"><b>تصدير الطلاب Excel</b><span>الاسم، الحلقة، الفئة، المسار، الجنس، الهوية، الميلاد وبقية البيانات الأساسية</span></button><button class="action-card" onclick="exportStudentsWord()"><b>تصدير الطلاب Word</b><span>نفس بيانات Excel في جدول Word منسق</span></button><button class="action-card" onclick="openStudentsPdfPreview()"><b>تصدير الطلاب PDF</b><span>معاينة داخل التطبيق ثم حفظ PDF مع التحكم بالخط والاتجاه</span></button></div>${canImport?`<div class="section-head"><h3>استيراد</h3></div><div class="data-actions"><button class="action-card" onclick="openImport('students')"><b>إضافة طلاب جماعياً</b><span>Excel، CSV، DOCX، PDF أو صورة بعد المراجعة — المكرر لا يُضاف</span></button>${advanced?`<button class="action-card" onclick="openImport('recitations')"><b>استيراد تسميعات سابقة</b><span>الطالب، التاريخ، النوع، الصفحات، الأخطاء والنقرات</span></button><button class="action-card" onclick="openImport('plans')"><b>استيراد الخطط</b><span>الأهداف الشهرية للطلاب</span></button>`:''}<button class="action-card" onclick="downloadImportTemplate('students')"><b>قالب الطلاب</b><span>يشمل الاسم والفئة والمسار وبقية البيانات الاختيارية</span></button></div><div class="notice" style="margin-top:12px">PDF والصور وWord لا تُعتمد مباشرة؛ يتم استخراج النص ثم مراجعته أولاً لتقليل أخطاء OCR والتنسيق.</div>`:''}`}
