async function exportStudentsExcel(){if(!window.XLSX)return toast('مكتبة Excel لم تُحمّل');let rows=studentDirectoryRows();if(!rows.length)return toast('لا يوجد طلاب للتصدير');let wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(rows);ws['!cols']=[{wch:5},{wch:30},{wch:28},{wch:18},{wch:20},{wch:10},{wch:16},{wch:16},{wch:14},{wch:18},{wch:28},{wch:18},{wch:28},{wch:16}];XLSX.utils.book_append_sheet(wb,ws,'الطلاب');let name=`طلاب_حلقتي_${today()}.xlsx`;if(isNativeHalaqati()){let b64=XLSX.write(wb,{bookType:'xlsx',type:'base64'});await saveOrShareBase64(b64,name,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}else XLSX.writeFile(wb,name)}
