async function readImportFile(file){if(!file)return;$('#importStatus').textContent='جاري قراءة الملف...';try{let ext=file.name.split('.').pop().toLowerCase(),rows=[],raw='';if(['xlsx','xls','csv'].includes(ext)){let ab=await file.arrayBuffer(),wb=XLSX.read(ab,{type:'array'}),ws=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(ws,{defval:'',raw:false});raw=XLSX.utils.sheet_to_csv(ws,{FS:'\t'})}else if(ext==='docx'){let ab=await file.arrayBuffer(),res=await mammoth.extractRawText({arrayBuffer:ab});raw=res.value}else if(ext==='pdf'){if(!window.pdfjsLib)throw new Error('تعذر تحميل قارئ PDF');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise,parts=[];for(let i=1;i<=pdf.numPages;i++){let pg=await pdf.getPage(i),tx=await pg.getTextContent();parts.push(tx.items.map(x=>x.str).join(' | '))}raw=parts.join('\n')}else if(file.type.startsWith('image/')){if(!window.Tesseract)throw new Error('تعذر تحميل OCR');$('#importStatus').textContent='جاري OCR العربي؛ قد يستغرق بعض الوقت...';let r=await Tesseract.recognize(file,'ara+eng',{logger:m=>{if(m.progress)$('#importStatus').textContent=`OCR ${Math.round(m.progress*100)}%`}});raw=r.data.text}else throw new Error('نوع ملف غير مدعوم');$('#importRaw').value=raw;if(rows.length){state.importRows=rows;showImportPreview()}else parseImportRaw();$('#importStatus').textContent=`تمت القراءة: ${file.name}. راجع الصفوف قبل الاعتماد.`}catch(e){$('#importStatus').textContent='خطأ: '+e.message}}
function parseImportRaw(){let raw=$('#importRaw').value.trim();if(!raw){state.importRows=[];return showImportPreview()}let lines=raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),delim=lines[0]?.includes('\t')?'\t':lines[0]?.includes('|')?'|':lines[0]?.includes(',')?',':null;if(!delim){state.importRows=lines.map(x=>({'الاسم':x}));return showImportPreview()}let headers=lines[0].split(delim).map(x=>x.trim());state.importRows=lines.slice(1).map(line=>Object.fromEntries(line.split(delim).map((v,i)=>[headers[i]||`حقل${i+1}`,v.trim()])));showImportPreview()}
