function importText(v){if(v==null)return '';if(typeof v==='number'&&Number.isFinite(v))return String(v).replace(/\.0+$/,'');return String(v).trim()}
function importDate(v){if(v==null||v==='')return null;if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,10);if(typeof v==='number'&&Number.isFinite(v)){let d=new Date(Date.UTC(1899,11,30)+Math.round(v)*86400000);return isNaN(d)?null:d.toISOString().slice(0,10)}let x=String(v).trim();if(!x)return null;if(/^\d{4}-\d{1,2}-\d{1,2}$/.test(x)){let [y,m,d]=x.split('-').map(Number);return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}let m=x.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);if(m){let d=+m[1],mo=+m[2],y=+m[3];if(y<100)y+=2000;if(mo>=1&&mo<=12&&d>=1&&d<=31)return `${String(y).padStart(4,'0')}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`}if(/^\d{4,5}$/.test(x)){let n=Number(x);if(n>20000&&n<80000){let d=new Date(Date.UTC(1899,11,30)+n*86400000);return d.toISOString().slice(0,10)}}return null}
