async function ensureImportCategory(hid,name){name=String(name||'').trim();if(!name)return null;let c=state.categories.find(x=>x.halaqa_id===hid&&normalizeNameJs(x.name)===normalizeNameJs(name));if(c)return c.id;let {data,error}=await db.from('student_categories').insert({halaqa_id:hid,name,created_by:state.user.id}).select().single();if(error){let again=state.categories.find(x=>x.halaqa_id===hid&&normalizeNameJs(x.name)===normalizeNameJs(name));if(again)return again.id;throw error}state.categories.push(data);return data.id}
