async function refreshAdminUsers({force=false,silent=true}={}){
  if(!canManageUsers())return false;
  if(!navigator.onLine){state.adminUsersFromCache=true;state.adminUsersError='لا يوجد اتصال بالإنترنت';return false}
  let fresh=state.adminUsersUpdatedAt&&Date.now()-Date.parse(state.adminUsersUpdatedAt)<10000;
  if(!force&&fresh&&state.users.length&&!state.adminUsersFromCache)return true;
  const fetchRows=async()=>{let q=db.from('profiles').select('id,full_name,email,phone,role,requested_role,approval_status,active,approved_at,rejection_reason,created_at').order('created_at',{ascending:false});let r=await withTimeout(q,8500,'profiles timeout');if(r.error)throw r.error;return r.data||[]};
  try{
    let rows;
    try{rows=await fetchRows()}catch(e){if(!isNetworkError(e))throw e;await sleep(550);rows=await fetchRows()}
    state.users=rows;state.adminUsersUpdatedAt=new Date().toISOString();state.adminUsersFromCache=false;state.adminUsersError='';state.networkVerified=true;state.offline=false;updateSyncBadge();cacheSnapshot();return true
  }catch(e){
    state.adminUsersFromCache=true;state.adminUsersError=String(e?.message||e||'تعذر تحميل الحسابات');if(!silent)toast('تعذر تحديث الحسابات من الخادم: '+state.adminUsersError);return false
  }
}
function adminUsersReadOnly(){return !navigator.onLine||!!state.adminUsersFromCache}
async function usersPage(){
  if(!canManageUsers())return '<div class="empty">إدارة الحسابات والصلاحيات متاحة لمسؤول النظام فقط.</div>';
  await refreshAdminUsers({force:false,silent:true});
  let readOnly=adminUsersReadOnly(),disabled=readOnly?' disabled':'',pending=state.users.filter(u=>u.approval_status==='pending'),approved=state.users.filter(u=>u.approval_status==='approved'),rejected=state.users.filter(u=>u.approval_status==='rejected');
  let row=u=>{let owner=u.role==='admin',requested=requestRoleAr[u.requested_role]||'ولي أمر',mainAction=owner?'—':u.approval_status==='pending'?`<button class="mini"${disabled} onclick="approveUser('${u.id}')">اعتماد</button><button class="mini red"${disabled} onclick="rejectUser('${u.id}')">رفض</button>`:u.approval_status==='rejected'?`<button class="mini"${disabled} onclick="approveUser('${u.id}')">اعتماد من جديد</button>`:`<button class="mini ${u.active?'red':''}"${disabled} onclick="toggleUserActive('${u.id}',${!u.active})">${u.active?'إيقاف':'تفعيل'}</button>`;let permanent=owner?'':`<button class="mini red user-delete-btn"${disabled} onclick="deleteUserPermanent('${u.id}')">حذف نهائي</button>`;return `<tr><td><b>${esc(u.full_name)}</b><div class="muted">${esc(u.phone||'')}</div></td><td>${esc(u.email||'—')}</td><td>${owner?'<span class="badge blue">مسؤول النظام</span>':u.approval_status==='pending'?`<select id="role_${u.id}"${disabled}><option value="guardian" ${u.requested_role==='guardian'?'selected':''}>ولي أمر</option><option value="teacher" ${u.requested_role==='teacher'?'selected':''}>محفّظ الحلقة</option><option value="supervisor" ${u.requested_role==='supervisor'?'selected':''}>مشرف الحلقات</option></select><div class="muted">الطلب: ${requested}</div>`:`<select${disabled} onchange="changeRole('${u.id}',this.value)"><option value="guardian" ${u.role==='guardian'?'selected':''}>ولي أمر</option><option value="teacher" ${u.role==='teacher'?'selected':''}>محفّظ الحلقة</option><option value="supervisor" ${u.role==='supervisor'?'selected':''}>مشرف الحلقات</option></select>`}</td><td>${u.approval_status==='pending'?'<span class="badge warn">بانتظار الاعتماد</span>':u.approval_status==='rejected'?'<span class="badge red">مرفوض</span>':u.active?'<span class="badge good">نشط</span>':'<span class="badge red">موقوف</span>'}</td><td><div class="actions">${mainAction}${permanent}</div></td></tr>`};
  let status=readOnly?(state.users.length?`<div class="notice"><b>عرض محفوظ للقراءة فقط:</b> تعذر تحديث الحسابات من الخادم. آخر تحديث: ${esc(state.adminUsersUpdatedAt||'غير معروف')}. <button class="mini" onclick="refreshAdminUsers({force:true,silent:false}).then(()=>render())">إعادة المحاولة</button></div>`:`<div class="notice"><b>تعذر تحميل الحسابات من الخادم.</b> لا توجد نسخة محلية محفوظة. <button class="mini" onclick="refreshAdminUsers({force:true,silent:false}).then(()=>render())">إعادة المحاولة</button></div>`):`<div class="muted" style="margin:8px 0">تم تحديث الحسابات من الخادم ${state.adminUsersUpdatedAt?esc(state.adminUsersUpdatedAt):''}</div>`;
  return `<div class="hero"><h2>الحسابات والصلاحيات</h2><p>كل حساب جديد يبقى معلقاً حتى تعتمد هويته وتحدد صلاحية الوصول. ويمكن لمسؤول النظام حذف الحساب غير الإداري نهائياً بعد تأكيد صريح.</p></div>${status}${pending.length?`<div class="section-head"><h3>طلبات جديدة (${pending.length})</h3></div><div class="notice">راجع الاسم والبريد ونوع الحساب المطلوب قبل الاعتماد أو الحذف النهائي.</div>`:''}<div style="height:10px"></div><div class="table-wrap"><table><thead><tr><th>المستخدم</th><th>البريد</th><th>الصلاحية</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${[...pending,...approved,...rejected].map(row).join('')}</tbody></table></div>`
}
async function deleteUserPermanent(id){
  if(!canManageUsers())return toast('الحذف النهائي لمسؤول النظام فقط');if(adminUsersReadOnly())return toast('تعديل الحسابات يحتاج اتصالاً مباشراً بالخادم');let u=state.users.find(x=>x.id===id);if(!u)return toast('الحساب غير موجود');if(u.role==='admin'||id===state.user?.id)return toast('لا يمكن حذف حساب مسؤول النظام');if(!navigator.onLine)return toast('الحذف النهائي يحتاج اتصالاً بالإنترنت');
  let ok=confirm(`حذف حساب «${u.full_name||u.email||'المستخدم'}» نهائياً؟\n\nسيُحذف تسجيل الدخول والملف والصلاحيات ولن يظهر الحساب مرة أخرى. ستبقى سجلات الحلقة والتسميعات التاريخية محفوظة.\n\nهل تريد المتابعة؟`);if(!ok)return;
  let {data,error}=await db.rpc('admin_delete_account',{target_user:id});if(error)return toast(error.message?.includes('admin_delete_account')?'شغّل ترحيل v2.17 في Supabase أولاً':error.message);if(data===false)return toast('تعذر حذف الحساب');state.users=state.users.filter(x=>x.id!==id);toast('تم حذف الحساب نهائياً');await loadAll();render()
}
async function approveUser(id){if(adminUsersReadOnly())return toast('تعديل الحسابات يحتاج اتصالاً مباشراً بالخادم');let el=$('#role_'+id),u=state.users.find(x=>x.id===id),role=el?.value||(u?.requested_role&&['guardian','teacher','supervisor'].includes(u.requested_role)?u.requested_role:'guardian');let {error}=await db.from('profiles').update({role,requested_role:role,approval_status:'approved',active:true,approved_at:new Date().toISOString(),approved_by:state.user.id,rejection_reason:null}).eq('id',id);if(error)return toast(error.message);toast('تم اعتماد الحساب وتحديد الصلاحية');await loadAll();render()}
