/* ----- faster cache also includes multi-supervisor mappings ----- */
function cacheSnapshot(){
  let k=cacheKey();if(!k||!state.profile)return;let snap={savedAt:new Date().toISOString(),page:state.page||'home',profile:state.profile,halaqas:state.halaqas,students:state.students,sessions:state.sessions,announcements:state.announcements,goals:state.goals,monthly:state.monthly,homeMonthly:state.homeMonthly,homeSelectedMonth:state.homeSelectedMonth,homeMonthlyLoadedKey:state.homeMonthlyLoadedKey,leaderDaily:state.leaderDaily,leaderMonthly:state.leaderMonthly,dailySummary:state.dailySummary,forum:state.forum,comments:state.comments,categories:state.categories,halaqaTeachers:state.halaqaTeachers,halaqaSupervisors:state.halaqaSupervisors,guardianAccounts:state.guardianAccounts,guardianDirectory:state.guardianDirectory,guardianRanksMonth:state.guardianRanksMonth,guardianRanksDay:state.guardianRanksDay,guardianRangeRanks:state.guardianRangeRanks,guardianRangeDashboards:state.guardianRangeDashboards||{},guardianCompetition:state.guardianCompetition,guardianDashboards:state.guardianDashboards||{},guardianTrendDays:state.guardianTrendDays||7,guardianPeriodMode:state.guardianPeriodMode,guardianPeriodDay:state.guardianPeriodDay,guardianPeriodMonth:state.guardianPeriodMonth,guardianPeriodFrom:state.guardianPeriodFrom,guardianPeriodTo:state.guardianPeriodTo,guardianChildFilter:state.guardianChildFilter,guardianAnalyticsUpdatedAt:state.guardianAnalyticsUpdatedAt,guardianAnalyticsError:state.guardianAnalyticsError,competitionTrack:state.competitionTrack,competitionPeriod:state.competitionPeriod,settings:state.settings,offlineRosterCache:state.offlineRosterCache,users:roleCanAdmin()?(state.users||[]):[],adminUsersUpdatedAt:state.adminUsersUpdatedAt||''};state.offlineSnapshotCache=cloneJson(snap);try{localStorage.setItem(k,JSON.stringify(snap))}catch(e){}let store=window.HalaqatiOfflineStore;if(store?.putSnapshot&&state.user?.id)store.putSnapshot(state.user.id,snap).catch(e=>console.warn('IndexedDB snapshot write failed',e))}
function restoreSnapshot(){let x=state.offlineSnapshotCache||readJsonLocal(cacheKey(),null)||readJsonLocal(legacyCacheKey(),null);if(!x||!x.profile)return false;try{state.profile=x.profile;try{let pr=readJsonLocal('halaqati_print_resume_v2407',null);let pg=pr&&Date.now()-Number(pr.at||0)<=20*60*1000?pr.page:x.page;let ok=['home','halaqas','community','notifications','sessions','students','plans','reports','certificates','competition','quran','ranking','data','settings','supervision','users'];if(ok.includes(pg))state.page=pg}catch(_e){};for(let p of ['halaqas','students','sessions','announcements','goals','monthly','leaderDaily','leaderMonthly','dailySummary','forum','comments','categories','halaqaTeachers','halaqaSupervisors','guardianAccounts','guardianDirectory'])state[p]=x[p]||[];state.homeMonthly=x.homeMonthly||[];state.homeSelectedMonth=x.homeSelectedMonth||today().slice(0,7);state.homeMonthlyLoadedKey=x.homeMonthlyLoadedKey||'';state.guardianRanksMonth=x.guardianRanksMonth||{};state.guardianRanksDay=x.guardianRanksDay||{};state.guardianRangeRanks=x.guardianRangeRanks||{};state.guardianRangeDashboards=x.guardianRangeDashboards||{};state.guardianCompetition=x.guardianCompetition||{};state.guardianDashboards=x.guardianDashboards||{};state.guardianTrendDays=Number(x.guardianTrendDays||7);state.guardianPeriodMode=x.guardianPeriodMode||'month';state.guardianPeriodDay=x.guardianPeriodDay||today();state.guardianPeriodMonth=x.guardianPeriodMonth||today().slice(0,7);state.guardianPeriodFrom=x.guardianPeriodFrom||monthStart();state.guardianPeriodTo=x.guardianPeriodTo||today();state.guardianChildFilter=x.guardianChildFilter||'all';state.guardianAnalyticsUpdatedAt=x.guardianAnalyticsUpdatedAt||'';state.guardianAnalyticsError=x.guardianAnalyticsError||'';state.competitionTrack=x.competitionTrack||'hifz';state.competitionPeriod=x.competitionPeriod||'month';state.settings=x.settings||null;state.offlineRosterCache=x.offlineRosterCache||{};state.users=roleCanAdmin()?(x.users||[]):[];state.adminUsersUpdatedAt=x.adminUsersUpdatedAt||'';state.adminUsersFromCache=roleCanAdmin()&&state.users.length>0;state.adminUsersError='';state.offline=true;return true}catch(e){return false}}

async function loadAll(forceNetwork=false){
  let online=forceNetwork?true:await internetReachable();
  if(!online){if(restoreSnapshot()){state.pendingSync=readOfflineQueue().length;applySavedTheme();updateSyncBadge();return}state.offline=true;updateSyncBadge();return}
  state.networkVerified=true;state.offline=false;
  let queries=[
    db.from('halaqas').select('*').order('created_at'),db.from('students').select('*').order('full_name'),db.from('sessions').select('*').order('session_date',{ascending:false}).limit(120),
    db.from('announcements').select('*').order('pinned',{ascending:false}).order('publish_at',{ascending:false}).limit(80),db.from('student_goals').select('*').gte('period_end',monthStart()).limit(300),
    db.from('monthly_student_stats').select('*').gte('month_start',monthStart()),db.from('leaderboard_daily').select('*').eq('period_date',today()),db.from('leaderboard_monthly').select('*').gte('month_start',monthStart()),
    db.from('daily_student_summary').select('*').eq('session_date',today()).limit(300),db.from('forum_posts').select('*').order('pinned',{ascending:false}).order('created_at',{ascending:false}).limit(80),
    db.from('forum_comments').select('*').order('created_at').limit(500),db.from('app_settings').select('*').eq('id',1).single(),db.from('student_categories').select('*').order('min_age',{ascending:true,nullsFirst:false}).order('name'),
    db.from('halaqa_teachers').select('*'),db.from('halaqa_supervisors').select('*')
  ];
  if(roleCanAdmin())queries.push(db.from('profiles').select('id,full_name,email,phone,role,requested_role,approval_status,active,approved_at,rejection_reason,created_at').order('created_at',{ascending:false}));
  let r;try{r=await withTimeout(Promise.all(queries),12000,'load timeout')}catch(e){state.networkVerified=false;state.offline=true;if(restoreSnapshot()){updateSyncBadge();return}throw e}
  let critical=r.slice(0,3).find(x=>x.error&&isNetworkError(x.error));if(critical&&restoreSnapshot()){state.networkVerified=false;state.offline=true;state.pendingSync=readOfflineQueue().length;updateSyncBadge();return}
  [state.halaqas,state.students,state.sessions,state.announcements,state.goals,state.monthly,state.leaderDaily,state.leaderMonthly,state.dailySummary,state.forum,state.comments]=r.slice(0,11).map(x=>x.data||[]);if(!state.homeSelectedMonth)state.homeSelectedMonth=today().slice(0,7);if(state.homeSelectedMonth===today().slice(0,7)){state.homeMonthly=[...state.monthly];state.homeMonthlyLoadedKey=state.homeSelectedMonth};
  state.settings=r[11]?.data||null;state.categories=r[12]?.data||[];state.halaqaTeachers=r[13]?.data||[];state.halaqaSupervisors=r[14]?.data||[];state.users=roleCanAdmin()?(r[15]?.data||[]):[];if(roleCanAdmin()&&state.users.length){state.adminUsersUpdatedAt=new Date().toISOString();state.adminUsersFromCache=false;state.adminUsersError=''};
  await loadRoleExtras();applySavedTheme();await loadPhotoUrls();state.pendingSync=readOfflineQueue().length;cacheSnapshot();updateSyncBadge()
}

