function supervisorIdsForHalaqa(hid){let ids=(state.halaqaSupervisors||[]).filter(x=>x.halaqa_id===hid).map(x=>x.supervisor_id),h=state.halaqas.find(x=>x.id===hid);if(h?.supervisor_id)ids.push(h.supervisor_id);return [...new Set(ids.filter(Boolean))]}
function supervisorNamesForHalaqa(hid){let ids=supervisorIdsForHalaqa(hid),names=ids.map(id=>state.users.find(u=>u.id===id)?.full_name).filter(Boolean);if(names.length)return names.join('، ');return ids.length?`${ids.length} مشرف`:'غير معيّن'}
function openSupervisorAssignments(hid){if(!isOwner())return toast('إدارة مشرفي الحلقات لمسؤول النظام فقط');$('#saHalaqa').value=hid;let assigned=new Set(supervisorIdsForHalaqa(hid)),rows=state.users.filter(u=>u.role==='supervisor'&&u.approval_status==='approved'&&u.active);$('#supervisorAssignList').innerHTML=rows.length?rows.map(u=>`<label class="supervisor-check"><input type="checkbox" name="saSupervisor" value="${u.id}" ${assigned.has(u.id)?'checked':''}><span><b>${esc(u.full_name)}</b><div class="muted">${esc(u.email||'')}</div></span></label>`).join(''):'<div class="empty">لا توجد حسابات مشرفين معتمدة بعد.</div>';supervisorAssignDlg.showModal()}
$('#supervisorAssignForm')?.addEventListener('submit',async e=>{e.preventDefault();if(!isOwner())return;let hid=$('#saHalaqa').value,wanted=[...document.querySelectorAll('input[name="saSupervisor"]:checked')].map(x=>x.value),old=(state.halaqaSupervisors||[]).filter(x=>x.halaqa_id===hid),oldIds=old.map(x=>x.supervisor_id),toAdd=wanted.filter(x=>!oldIds.includes(x)),toDel=oldIds.filter(x=>!wanted.includes(x));try{if(toDel.length){let q=await db.from('halaqa_supervisors').delete().eq('halaqa_id',hid).in('supervisor_id',toDel);if(q.error)throw q.error}if(toAdd.length){let q=await db.from('halaqa_supervisors').insert(toAdd.map(supervisor_id=>({halaqa_id:hid,supervisor_id,created_by:state.user.id})));if(q.error)throw q.error}let q=await db.from('halaqas').update({supervisor_id:wanted[0]||null}).eq('id',hid);if(q.error)throw q.error;supervisorAssignDlg.close();toast('تم تحديث مشرفي الحلقة');await loadAll();render()}catch(err){toast('تعذر حفظ المشرفين: '+(err?.message||err))}})
function halaqasPage(){if(!roleCanManage())return '<div class="empty">لا توجد حلقات متاحة.</div>';return `<div class="hero"><h2>${isOwner()?'إدارة الحلقات والفئات':'الحلقات والفئات'}</h2><p>يمكن ربط أكثر من مشرف وأكثر من محفّظ بالحَلَقة، والمشرف الواحد يستطيع متابعة أكثر من حلقة.</p></div><div class="section-head"><h3>الحلقات (${state.halaqas.length})</h3>${isOwner()?'<button class="btn btn-primary" onclick="openHalaqa()">+ حلقة</button>':''}</div>${state.halaqas.map(h=>{let cats=state.categories.filter(c=>c.halaqa_id===h.id&&c.active!==false),sts=activeStudents().filter(s=>s.halaqa_id===h.id),tids=state.halaqaTeachers.filter(x=>x.halaqa_id===h.id).map(x=>x.teacher_id),teachers=state.users.filter(u=>tids.includes(u.id)),sids=supervisorIdsForHalaqa(h.id);return `<div class="card"><div class="row"><div class="avatar">ح</div><div class="grow"><b>${esc(h.name)}</b><div class="muted">${esc(h.location||'المكان غير محدد')} · ${esc(h.schedule_text||'البرنامج غير محدد')}</div><div class="muted">المشرفون: ${esc(supervisorNamesForHalaqa(h.id))} · المحفّظون: ${teachers.length?teachers.map(x=>esc(x.full_name)).join('، '):(state.profile.role==='teacher'?'أنت / حسب الربط':'غير معيّنين')}</div></div><span class="badge">${h.active===false?'موقوفة':'نشطة'}</span>${typeof rc27TypeBadge==='function'?rc27TypeBadge(h):''}</div><div class="structure-grid"><div class="structure-item"><b>${sts.length}</b>طالب</div><div class="structure-item"><b>${cats.length}</b>فئة</div><div class="structure-item"><b>${sids.length}</b>مشرف</div></div><div class="actions">${isOwner()?`<button class="mini" onclick="openHalaqa('${h.id}')">تعديل الحلقة</button><button class="mini red" onclick="deleteHalaqaCascade('${h.id}')">حذف الحلقة</button><button class="mini" onclick="openSupervisorAssignments('${h.id}')">المشرفون</button>`:''}<button class="mini" onclick="openCategories('${h.id}')">الفئات</button>${['admin','supervisor'].includes(state.profile.role)?`<button class="mini" onclick="openTeacherAssignments('${h.id}')">المحفّظون</button>`:''}<button class="mini" onclick="goToHalaqaStudents('${h.id}')">طلاب الحلقة</button>${typeof rc27ParticipantsButton==='function'?rc27ParticipantsButton(h):''}</div><div class="muted" style="margin-top:9px">المسارات: حفظ عام ${sts.filter(s=>s.track_code==='general_hifz').length} · تثبيت ${sts.filter(s=>s.track_code==='tathbit').length} · بدون مسار ${sts.filter(s=>!s.track_code).length}</div></div>`}).join('')||'<div class="empty">لا توجد حلقات بعد.</div>'}`}

/* ----- v2.8.2 delete controls + monthly plan display ----- */
function currentGoalForStudent(sid){let now=monthStart();return state.goals.find(g=>g.student_id===sid&&String(g.period_start||'').slice(0,7)===now.slice(0,7))||state.goals.find(g=>g.student_id===sid)}
function plansPage(){let rows=activeStudents().map(s=>({s,g:currentGoalForStudent(s.id),m:state.monthly.find(m=>m.student_id===s.id)||{}}));return `<div class="hero"><h2>الخطط الشهرية</h2><p>حدد هدف كل طالب، وتابع الإنجاز والورد اليومي، مع إمكانية تعديل الخطة أو حذفها.</p></div><div class="section-head"><h3>خطط الشهر</h3>${roleCanManage()?'<button class="btn btn-primary" onclick="openPlan()">+ خطة</button>':''}</div>${rows.map(({s,g,m})=>{if(!g)return `<div class="card row">${avatarHtml(s)}<div class="grow"><b>${esc(s.full_name)}</b><div class="muted">لا توجد خطة لهذا الشهر</div></div>${roleCanManage()?`<button class="mini" onclick="openPlan('${s.id}')">إضافة</button>`:''}</div>`;let hp=Math.min(100,Math.round(Number(m.hifz_pages||0)/Math.max(Number(g.target_hifz_pages||1),1)*100)),rp=Math.min(100,Math.round(Number(m.review_pages||0)/Math.max(Number(g.target_review_pages||1),1)*100)),sp=Math.min(100,Math.round(Number(m.sard_pages||0)/Math.max(Number(g.target_sard_pages||1),1)*100));return `<div class="card"><div class="row">${avatarHtml(s)}<div class="grow"><b>${esc(s.full_name)}</b><div class="muted">${String(g.period_start||'').slice(0,7)} · الورد اليومي: حفظ ${fmt(g.target_daily_hifz_pages)} · مراجعة ${fmt(g.target_daily_review_pages)} · سرد ${fmt(g.target_daily_sard_pages)} صفحة</div></div></div><div class="plan-target-grid"><div><b>${fmt(g.target_hifz_pages)}</b><span>هدف الحفظ</span></div><div><b>${fmt(g.target_review_pages)}</b><span>هدف المراجعة</span></div><div><b>${fmt(g.target_sard_pages)}</b><span>هدف السرد</span></div><div><b>${fmt(g.expected_session_days||0)}</b><span>أيام الخطة</span></div></div>${planProgress('الحفظ',hp,m.hifz_pages,g.target_hifz_pages)}${planProgress('المراجعة',rp,m.review_pages,g.target_review_pages)}${planProgress('السرد',sp,m.sard_pages,g.target_sard_pages)}${g.note?`<div class="muted" style="margin-top:10px">ملاحظة: ${esc(g.note)}</div>`:''}${roleCanManage()?`<div class="plan-card-actions"><button class="mini" onclick="openPlan('${s.id}','${g.id}')">تعديل الخطة</button><button class="mini red" onclick="deleteMonthlyPlan('${g.id}')">حذف الخطة نهائياً</button></div>`:''}</div>`}).join('')}`}
function openPlan(sid='',gid=''){fillStudents($('#plStudent'),sid);let g=gid?state.goals.find(x=>x.id===gid):(sid?currentGoalForStudent(sid):null);$('#plMonth').value=g?String(g.period_start||monthStart()).slice(0,7):monthStart().slice(0,7);$('#plHifz').value=g?.target_hifz_pages??40;$('#plReview').value=g?.target_review_pages??120;$('#plSard').value=g?.target_sard_pages??40;$('#plDays').value=g?.expected_session_days??20;$('#plNote').value=g?.note||'';planDlg.showModal()}
async function deleteMonthlyPlan(id){if(!roleCanManage())return;let g=state.goals.find(x=>x.id===id);if(!g)return toast('الخطة غير موجودة');let st=state.students.find(x=>x.id===g.student_id);if(!confirm(`حذف خطة ${st?.full_name||'الطالب'} لشهر ${String(g.period_start||'').slice(0,7)} نهائياً؟\nلن تُحذف التسميعات الفعلية.`))return;if(!navigator.onLine||state.offline)return toast('حذف الخطة يحتاج اتصالاً بالإنترنت');try{let {data,error}=await db.from('student_goals').delete().eq('id',id).select('id');if(error)throw error;if(!data?.length)throw new Error('لم تسمح الصلاحيات بحذف الخطة');state.goals=state.goals.filter(x=>x.id!==id);toast('تم حذف الخطة الشهرية');await loadAll();render()}catch(e){toast('تعذر حذف الخطة: '+(e?.message||e))}}

/* ----- v2.8.2 professional report studio ----- */
const reportTrackAr={all:'جميع المسارات',general_hifz:'مسار الحفظ العام',tathbit:'مسار التثبيت'};
function reportBounds(){if(state.reportMode==='day'){let d=state.reportDay||today();return {from:d,to:d}}if(state.reportMode==='month'){let ym=state.reportMonth||today().slice(0,7);return {from:ym+'-01',to:monthEnd(ym)}}return {from:state.reportFrom,to:state.reportTo}}
function reportStudents(trackOverride=null){let rows=activeStudents(),track=trackOverride??state.reportTrack??'all';if(state.reportHalaqa&&state.reportHalaqa!=='all')rows=rows.filter(x=>x.halaqa_id===state.reportHalaqa);if(track&&track!=='all')rows=rows.filter(x=>x.track_code===track);return rows}
function reportTrackLabel(track=state.reportTrack){return reportTrackAr[track]||studentTrackAr[track]||'جميع المسارات'}
function reportKey(){let b=reportBounds();return `${state.reportMode}:${b.from}:${b.to}:${state.reportHalaqa}:${state.reportTrack}:${state.reportSessionType}`}
function reportHalaqas(){let ids=[...new Set(reportStudents().map(x=>x.halaqa_id))];return ids.map(id=>state.halaqas.find(h=>h.id===id)).filter(Boolean)}
function reportMainHalaqa(){let hs=reportHalaqas();return hs.length===1?hs[0]:null}
function reportPeriodLabel(){let b=reportBounds();return b.from===b.to?b.from:`${b.from} إلى ${b.to}`}
function reportFileStamp(){return `${reportTypeLabel(state.reportType)}_${reportTrackLabel()}_${reportPeriodLabel()}`.replace(/[^\d\u0600-\u06FF_-]+/g,'_')}
function reportTypeLabel(t){return {leaders:'لائحة_الأوائل',points:'نقاط_الطلاب',students:'تقارير_الطلاب',halaqa:'تقرير_الحلقة',attendance:'حضور_الحلقة',recitations:'سجل_التسميعات'}[t]||'تقرير'}
function reportTypeTitle(t){return {leaders:'لائحة الأوائل',points:'نقاط الطلاب',students:'تقرير لكل طالب',halaqa:'تقرير الحلقة',attendance:'حضور الحلقة',recitations:'سجل التسميعات'}[t]||'تقرير الحلقة'}
function reportSessions(){return state.reportData?.sessions||[]}
function reportAttendance(){return state.reportData?.attendance||[]}
function reportRecitations(){return state.reportData?.recitations||[]}
function reportNotes(){return state.reportData?.notes||[]}
function recPoints(r){if(r.points!=null)return Number(r.points||0);return Math.max(0,Number(r.pages_count||0)-(Number(r.mistakes||0)+Number(r.prompts||0)*.5)*.25)}
function recGroup(r,st){if(r.activity_type==='new_hifz')return st?.track_code==='tathbit'?'tathbit':'hifz';if(String(r.activity_type||'').includes('review'))return 'review';if(r.activity_type==='sard')return 'sard';return 'tilawah'}
function reportStatsRows(trackOverride=null){let students=reportStudents(trackOverride),sidSet=new Set(students.map(x=>x.id)),sessions=reportSessions(),seSet=new Set(sessions.map(x=>x.id)),at=reportAttendance().filter(x=>sidSet.has(x.student_id)&&seSet.has(x.session_id)),recs=reportRecitations().filter(x=>sidSet.has(x.student_id)&&seSet.has(x.session_id)),notes=reportNotes().filter(x=>sidSet.has(x.student_id)&&seSet.has(x.session_id));return students.map(st=>{let a=at.filter(x=>x.student_id===st.id),rr=recs.filter(x=>x.student_id===st.id),nn=notes.filter(x=>x.student_id===st.id),out={student:st,hifzPages:0,tathbitPages:0,reviewPages:0,sardPages:0,tilawahPages:0,mistakes:0,prompts:0,points:0,present:0,absent:0,excused:0,late:0,notes:nn};for(let x of a){if(x.status==='present')out.present++;else if(x.status==='absent')out.absent++;else if(x.status==='excused')out.excused++;else if(x.status==='late')out.late++}for(let r of rr){let g=recGroup(r,st),p=Number(r.pages_count||0);if(g==='hifz')out.hifzPages+=p;else if(g==='tathbit')out.tathbitPages+=p;else if(g==='review')out.reviewPages+=p;else if(g==='sard')out.sardPages+=p;else out.tilawahPages+=p;out.mistakes+=Number(r.mistakes||0);out.prompts+=Number(r.prompts||0);out.points+=recPoints(r)}out.totalPages=out.hifzPages+out.tathbitPages+out.reviewPages+out.sardPages+out.tilawahPages;out.sessions=a.length;return out}).filter(x=>x.totalPages>0||x.present+x.absent+x.excused+x.late>0||x.notes.length>0).sort((a,b)=>b.points-a.points||b.totalPages-a.totalPages||a.student.full_name.localeCompare(b.student.full_name,'ar'))}
function reportFilterHtml(){
  let hs=state.halaqas,modes=`<div class="report-period-tabs"><button class="${state.reportMode==='day'?'active':''}" onclick="setReportMode('day')">يوم معين</button><button class="${state.reportMode==='range'?'active':''}" onclick="setReportMode('range')">فترة</button><button class="${state.reportMode==='month'?'active':''}" onclick="setReportMode('month')">شهر معين</button></div>`,dateInputs=state.reportMode==='day'?`<label class="field"><span>اليوم</span><input class="input" type="date" value="${esc(state.reportDay)}" onchange="state.reportDay=this.value;state.reportLoadedKey=''" ></label>`:state.reportMode==='month'?`<label class="field"><span>الشهر</span><input class="input" type="month" value="${esc(state.reportMonth)}" onchange="state.reportMonth=this.value;state.reportLoadedKey=''" ></label>`:`<label class="field"><span>من</span><input class="input" type="date" value="${esc(state.reportFrom)}" onchange="state.reportFrom=this.value;state.reportLoadedKey=''" ></label><label class="field"><span>إلى</span><input class="input" type="date" value="${esc(state.reportTo)}" onchange="state.reportTo=this.value;state.reportLoadedKey=''" ></label>`;
  return `<div class="report-control-card">${modes}<div class="report-control-grid">${dateInputs}<label class="field"><span>الحلقة</span><select onchange="state.reportHalaqa=this.value;state.reportLoadedKey='';render()"><option value="all">جميع الحلقات</option>${hs.map(h=>`<option value="${h.id}" ${state.reportHalaqa===h.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label><label class="field"><span>المسار</span><select onchange="state.reportTrack=this.value;state.reportLoadedKey='';render()"><option value="all" ${state.reportTrack==='all'?'selected':''}>جميع المسارات</option><option value="general_hifz" ${state.reportTrack==='general_hifz'?'selected':''}>مسار الحفظ العام</option><option value="tathbit" ${state.reportTrack==='tathbit'?'selected':''}>مسار التثبيت</option></select><small class="muted">الترتيب والنقاط تُحسب داخل المسار المختار فقط.</small></label><label class="field"><span>نوع اللقاء</span><select onchange="state.reportSessionType=this.value;state.reportLoadedKey='';render()"><option value="all">جميع الأنواع</option>${Object.entries(sesAr).map(([k,v])=>`<option value="${k}" ${state.reportSessionType===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="report-option-row"><label><input type="checkbox" ${state.reportIncludePhotos?'checked':''} onchange="state.reportIncludePhotos=this.checked;render()"> صور الطلاب</label><label><input type="checkbox" ${state.reportIncludeBirthDate?'checked':''} onchange="state.reportIncludeBirthDate=this.checked;render()"> تاريخ الميلاد</label><label><input type="checkbox" ${state.reportIncludeTeacher?'checked':''} onchange="state.reportIncludeTeacher=this.checked;render()"> معلومات المحفّظ</label></div><button class="btn btn-primary" style="width:100%;margin-top:10px" onclick="loadSelectedReport()" ${state.reportLoading?'disabled aria-busy="true"':''}>${state.reportLoading?'جاري تجهيز التقرير…':'تجهيز التقرير'}</button>${state.reportLoading?'<div class="report-loading">جاري جلب بيانات التقرير…</div>':''}</div>`
}

function reportTypeGrid(){let items=[['leaders','🏆','لائحة الأوائل','منصة أوائل + ترتيب كامل'],['points','▥','نقاط الطلاب','تفصيل النقاط والصفحات'],['students','👤','تقرير لكل طالب','ملخص + تسميعات + تعليقات'],['halaqa','▦','تقرير حلقة','إنجازات وجداول شاملة'],['attendance','☑','حضور الحلقة','اللقاءات + سجل الحضور'],['recitations','📖','سجل التسميعات','كل التسميعات بالتفصيل']];return `<div class="report-type-grid">${items.map(x=>`<button class="report-type-card ${state.reportType===x[0]?'active':''}" onclick="setReportType('${x[0]}')"><span class="rti">${x[1]}</span><span><b>${x[2]}</b><small>${x[3]}</small></span></button>`).join('')}</div>`}
function setReportType(t){state.reportType=t;render()}
function setReportMode(m){state.reportMode=m;state.reportLoadedKey='';if(m==='day'&&!state.reportDay)state.reportDay=today();if(m==='month'&&!state.reportMonth)state.reportMonth=today().slice(0,7);if(m==='range'){if(!state.reportFrom)state.reportFrom=monthStart();if(!state.reportTo)state.reportTo=today()}render()}
function setReportTab(t){setReportMode(t==='daily'?'day':'month')}
async function reportQueryIn(table,ids){let out=[];for(let i=0;i<ids.length;i+=80){let r=await db.from(table).select('*').in('session_id',ids.slice(i,i+80));if(r.error)throw r.error;out.push(...(r.data||[]))}return out}
function offlineReportFromCache(){let b=reportBounds(),sessions=state.sessions.filter(s=>s.session_date>=b.from&&s.session_date<=b.to&&(state.reportHalaqa==='all'||s.halaqa_id===state.reportHalaqa)&&(state.reportSessionType==='all'||s.session_type===state.reportSessionType)),attendance=[],notes=[],recitations=[];for(let se of sessions){let c=state.offlineRosterCache?.[se.id];if(c){attendance.push(...(c.attendance||[]));notes.push(...(c.notes||[]));recitations.push(...(c.recitations||[]))}}return {sessions,attendance,notes,recitations}}
async function loadSelectedReport(){if(state.reportLoading)return;let b=reportBounds();if(!b.from||!b.to||b.from>b.to)return toast('تأكد من تاريخ البداية والنهاية');if(!(await internetReachable())){let cached=offlineReportFromCache();if(!cached.sessions.length&&state.reportMode==='day'&&state.reportDay===today()){state.reportRows=state.dailySummary||[];return toast('لا توجد تفاصيل جلسات مخزنة محلياً لهذا التقرير')}state.reportData=cached;state.reportLoadedKey=reportKey();render();return toast('تم تجهيز التقرير من البيانات المخزنة على الجهاز')}state.reportLoading=true;render();try{let q=db.from('sessions').select('*').neq('status','cancelled').gte('session_date',b.from).lte('session_date',b.to).order('session_date',{ascending:true}).limit(600);if(state.reportHalaqa!=='all')q=q.eq('halaqa_id',state.reportHalaqa);if(state.reportSessionType!=='all')q=q.eq('session_type',state.reportSessionType);let sr=await q;if(sr.error)throw sr.error;let sessions=sr.data||[],ids=sessions.map(x=>x.id),attendance=[],recitations=[],notes=[];if(ids.length)[attendance,recitations,notes]=await Promise.all([reportQueryIn('attendance_records',ids),reportQueryIn('recitation_entries',ids),reportQueryIn('student_daily_notes',ids)]);state.reportData={sessions,attendance,recitations,notes};state.reportLoadedKey=reportKey();cacheSnapshot();}catch(e){toast('تعذر تجهيز التقرير: '+(e?.message||e))}finally{state.reportLoading=false;render()}}
function reportReadySummaryHtml(){if(state.reportLoadedKey!==reportKey())return `<div class="report-ready-card"><div class="report-ready-head"><div class="report-ready-icon">▤</div><div class="grow"><b>التقرير غير مجهّز بعد</b><span>${state.reportError?esc(state.reportError):'حدد الفترة والحلقة والنوع ثم اضغط «تجهيز التقرير».'}</span></div></div></div>`;let rows=reportStatsRows(),sessions=reportSessions(),h=reportMainHalaqa(),source=state.reportSource==='cache'?'نسخة محفوظة على الجهاز':'بيانات مباشرة من الخادم',updated=state.reportUpdatedAt?` · ${esc(state.reportUpdatedAt)}`:'';return `<div class="report-ready-card"><div class="report-ready-head"><div class="report-ready-icon">✓</div><div class="grow"><b>${esc(reportTypeTitle(state.reportType))} جاهز</b><span>${esc(h?.name||'جميع الحلقات')} · ${esc(reportTrackLabel())} · ${esc(reportPeriodLabel())}</span><span>${source}${updated}</span>${state.reportError?`<span role="status">${esc(state.reportError)}</span>`:''}</div></div><div class="report-ready-grid"><div class="box"><b>${rows.length}</b><span>طالب</span></div><div class="box"><b>${sessions.length}</b><span>لقاء</span></div><div class="box"><b>${fmt(rows.reduce((a,x)=>a+x.totalPages,0))}</b><span>إجمالي الصفحات</span></div><div class="box"><b>${fmt(rows.reduce((a,x)=>a+x.points,0))}</b><span>إجمالي النقاط</span></div></div></div>`}
function reportHeader(title,sub='',trackOverride=''){let h=reportMainHalaqa(),track=trackOverride||state.reportTrack||'all';return `<div class="pro-head"><div class="pro-head-logo">ح</div><div class="pro-head-title"><h1>حلقتي</h1><p>${esc(title)}${sub?' · '+esc(sub):''}</p></div><div class="pro-head-logo">۞</div></div><div class="pro-meta"><span><b>الحلقة:</b> ${esc(h?.name||'جميع الحلقات')}</span><span><b>المسار:</b> ${esc(reportTrackLabel(track))}</span><span><b>الفترة:</b> ${esc(reportPeriodLabel())}</span><span><b>تاريخ الإصدار:</b> ${today()}</span></div>`}
function proFooter(){return `<div class="pro-footer"><span>حلقتي · النظام الرسمي لإدارة ومتابعة حلقات القرآن الكريم</span><span>الإصدار ${APP_VERSION_NAME}</span></div>`}
function kpiHtml(rows){return `<div class="pro-kpis"><div class="pro-kpi"><b>${rows.length}</b><span>طلاب</span></div><div class="pro-kpi"><b>${fmt(rows.reduce((a,x)=>a+x.hifzPages,0))}</b><span>حفظ</span></div><div class="pro-kpi"><b>${fmt(rows.reduce((a,x)=>a+x.reviewPages,0))}</b><span>مراجعة</span></div><div class="pro-kpi"><b>${fmt(rows.reduce((a,x)=>a+x.sardPages,0))}</b><span>سرد</span></div><div class="pro-kpi"><b>${rows.reduce((a,x)=>a+x.present,0)}</b><span>حضور</span></div><div class="pro-kpi"><b>${rows.reduce((a,x)=>a+x.absent+x.excused,0)}</b><span>غياب</span></div></div>`}
function halaqaReportSection(rows,track=''){return `<section class="pro-report-page">${reportHeader('التقرير الشامل للحلقة','',track)}${kpiHtml(rows)}<div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>#</th><th>الطالب</th><th>الفئة</th><th>المسار</th><th>الحفظ</th><th>التثبيت</th><th>المراجعة</th><th>السرد</th><th>النقاط</th><th>حضور</th><th>غياب</th><th>أخطاء</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td class="name">${esc(x.student.full_name)}</td><td>${esc(categoryName(x.student))}</td><td>${esc(studentTrackAr[x.student.track_code]||'—')}</td><td>${fmt(x.hifzPages)}</td><td>${fmt(x.tathbitPages)}</td><td>${fmt(x.reviewPages)}</td><td>${fmt(x.sardPages)}</td><td><b>${fmt(x.points)}</b></td><td>${x.present}</td><td>${x.absent+x.excused}</td><td>${x.mistakes}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="report-empty-pro">لا توجد بيانات في الفترة المحددة.</div>'}${proFooter()}</section>`}
function halaqaReportHtml(){if(state.reportTrack==='all'){let sections=['general_hifz','tathbit'].map(t=>halaqaReportSection(reportStatsRows(t),t)).join('');return `<div class="pro-report">${sections}</div>`}return `<div class="pro-report">${halaqaReportSection(reportStatsRows(),state.reportTrack)}</div>`}
function leadersReportSection(rows,track=''){rows=rows.slice().sort((a,b)=>b.points-a.points),top=rows.slice(0,3);return `<section class="pro-report-page">${reportHeader('لائحة الأوائل','',track)}${top.length?`<div class="podium">${[top[1],top[0],top[2]].filter(Boolean).map((x,i)=>{let actual=i===0&&top[1]?2:i===1?1:3,cl=actual===1?'first':actual===2?'second':'third';return `<div class="podium-person ${cl}">${state.reportIncludePhotos?`<div class="podium-avatar">${state.photoUrls[x.student.id]?`<img src="${state.photoUrls[x.student.id]}">`:esc(x.student.full_name[0])}</div>`:''}<div class="podium-step"><div class="podium-rank">${actual}</div><div class="podium-name">${esc(x.student.full_name)}</div><div class="podium-score">${fmt(x.points)} نقطة · ${fmt(x.totalPages)} ص</div></div></div>`}).join('')}</div>`:''}<div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>الترتيب</th><th>الطالب</th><th>النقاط</th><th>الصفحات</th><th>الأخطاء</th><th>الحضور</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td class="name">${esc(x.student.full_name)}</td><td>${fmt(x.points)}</td><td>${fmt(x.totalPages)}</td><td>${x.mistakes}</td><td>${x.present}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="report-empty-pro">لا توجد بيانات لهذا المسار.</div>'}${proFooter()}</section>`}
function leadersReportHtml(){if(state.reportTrack==='all')return `<div class="pro-report">${['general_hifz','tathbit'].map(t=>leadersReportSection(reportStatsRows(t),t)).join('')}</div>`;return `<div class="pro-report">${leadersReportSection(reportStatsRows(),state.reportTrack)}</div>`}
function pointsReportSection(rows,track=''){return `<section class="pro-report-page">${reportHeader('نقاط الطلاب','',track)}${kpiHtml(rows)}<div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>الطالب</th><th>حفظ</th><th>تثبيت</th><th>مراجعة</th><th>سرد</th><th>أخطاء</th><th>نقرات</th><th>المجموع</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="name">${esc(x.student.full_name)}</td><td>${fmt(x.hifzPages)}</td><td>${fmt(x.tathbitPages)}</td><td>${fmt(x.reviewPages)}</td><td>${fmt(x.sardPages)}</td><td>${x.mistakes}</td><td>${x.prompts}</td><td><b>${fmt(x.points)}</b></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="report-empty-pro">لا توجد بيانات لهذا المسار.</div>'}${proFooter()}</section>`}
function pointsReportHtml(){if(state.reportTrack==='all')return `<div class="pro-report">${['general_hifz','tathbit'].map(t=>pointsReportSection(reportStatsRows(t),t)).join('')}</div>`;return `<div class="pro-report">${pointsReportSection(reportStatsRows(),state.reportTrack)}</div>`}

function attendanceReportSection(rows,track=''){return `<section class="pro-report-page">${reportHeader('حضور الحلقة','',track)}${kpiHtml(rows)}<div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>الطالب</th><th>حاضر</th><th>غائب</th><th>بعذر</th><th>متأخر</th><th>إجمالي التسجيلات</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="name">${esc(x.student.full_name)}</td><td>${x.present}</td><td>${x.absent}</td><td>${x.excused}</td><td>${x.late}</td><td>${x.present+x.absent+x.excused+x.late}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="report-empty-pro">لا توجد بيانات حضور لهذا المسار.</div>'}${proFooter()}</section>`}
function attendanceReportHtml(){if(state.reportTrack==='all')return `<div class="pro-report">${['general_hifz','tathbit'].map(t=>attendanceReportSection(reportStatsRows(t),t)).join('')}</div>`;return `<div class="pro-report">${attendanceReportSection(reportStatsRows(),state.reportTrack)}</div>`}
function recitationRangeForReport(r){if(r.start_page&&r.end_page)return `ص ${r.start_page}–${r.end_page}`;if(r.start_surah&&r.start_ayah)return `${surahs[(r.start_surah||1)-1]||''} ${r.start_ayah}${r.end_surah?` → ${surahs[(r.end_surah||1)-1]||''} ${r.end_ayah||''}`:''}`;if(Array.isArray(r.selected_surahs)&&r.selected_surahs.length)return r.selected_surahs.map(n=>surahs[n-1]).join('، ');let j=r.selection_data?.selected_juz;if(Array.isArray(j)&&j.length)return `الأجزاء ${j.join('، ')}`;return `${fmt(r.pages_count)} صفحة`}
function recitationsReportSection(track=''){let seMap=Object.fromEntries(reportSessions().map(s=>[s.id,s])),stMap=Object.fromEntries(state.students.map(s=>[s.id,s])),studentIds=new Set(reportStudents(track||null).map(x=>x.id)),rows=reportRecitations().filter(r=>studentIds.has(r.student_id)).slice().sort((a,b)=>(seMap[a.session_id]?.session_date||'').localeCompare(seMap[b.session_id]?.session_date||''));return `<section class="pro-report-page">${reportHeader('سجل التسميعات','',track)}<div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>التاريخ</th><th>الطالب</th><th>النوع</th><th>النطاق</th><th>صفحات</th><th>أخطاء</th><th>نقرات</th><th>تقييم</th><th>نقاط</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${seMap[r.session_id]?.session_date||'—'}</td><td class="name">${esc(stMap[r.student_id]?.full_name||'—')}</td><td>${esc(actAr[r.activity_type]||r.activity_type||'—')}</td><td>${esc(recitationRangeForReport(r))}</td><td>${fmt(r.pages_count)}</td><td>${r.mistakes||0}</td><td>${r.prompts||0}</td><td>${esc(evalAr[r.evaluation]||r.evaluation||r.rating||'—')}</td><td>${fmt(recPoints(r))}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="report-empty-pro">لا توجد تسميعات لهذا المسار.</div>'}${proFooter()}</section>`}
function recitationsReportHtml(){if(state.reportTrack==='all')return `<div class="pro-report">${['general_hifz','tathbit'].map(t=>recitationsReportSection(t)).join('')}</div>`;return `<div class="pro-report">${recitationsReportSection(state.reportTrack)}</div>`}
function studentSingleReportHtml(x,i,total,track=''){let st=x.student,recs=reportRecitations().filter(r=>r.student_id===st.id),notes=reportNotes().filter(n=>n.student_id===st.id),seMap=Object.fromEntries(reportSessions().map(s=>[s.id,s]));return `<section class="pro-report-page">${reportHeader(`تقرير الطالب ${i+1}/${total}`,st.full_name,track||st.track_code)}<div class="student-report-card">${state.reportIncludePhotos?`<div class="student-report-photo">${state.photoUrls[st.id]?`<img src="${state.photoUrls[st.id]}">`:esc(st.full_name[0])}</div>`:''}<div><h2 style="margin:0;color:#0d3b2f">${esc(st.full_name)}</h2><div class="student-info-grid"><div>المسار<b>${esc(studentTrackAr[st.track_code]||'—')}</b></div><div>الفئة<b>${esc(categoryName(st))}</b></div>${state.reportIncludeBirthDate?`<div>الميلاد<b>${esc(st.date_of_birth||'—')}</b></div>`:''}<div>الحفظ<b>${fmt(x.hifzPages)} ص</b></div><div>المراجعة<b>${fmt(x.reviewPages)} ص</b></div><div>السرد<b>${fmt(x.sardPages)} ص</b></div></div></div></div><div class="pro-section-title">التسميعات</div><div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>التاريخ</th><th>النوع</th><th>النطاق</th><th>صفحات</th><th>أخطاء</th><th>نقاط</th></tr></thead><tbody>${recs.map(r=>`<tr><td>${seMap[r.session_id]?.session_date||'—'}</td><td>${esc(actAr[r.activity_type]||r.activity_type||'—')}</td><td>${esc(recitationRangeForReport(r))}</td><td>${fmt(r.pages_count)}</td><td>${r.mistakes||0}</td><td>${fmt(recPoints(r))}</td></tr>`).join('')}</tbody></table></div>${notes.length?`<div class="pro-section-title">تعليقات ومتابعة</div><div class="pro-table-wrap"><table class="pro-table"><thead><tr><th>التاريخ</th><th>السلوك</th><th>الواجب</th><th>تعليق المحفّظ</th></tr></thead><tbody>${notes.map(n=>`<tr><td>${seMap[n.session_id]?.session_date||'—'}</td><td>${esc(behAr[n.behavior]||n.behavior||'—')}</td><td class="text-cell">${esc(n.homework||'—')}</td><td class="text-cell">${esc(n.teacher_comment||'—')}</td></tr>`).join('')}</tbody></table></div>`:''}${proFooter()}</section>`}
