function studentsReportHtml(){if(state.reportTrack==='all')return `<div class="pro-report">${['general_hifz','tathbit'].map(t=>studentsReportSection(reportStatsRows(t),t)).join('')}</div>`;return `<div class="pro-report">${studentsReportSection(reportStatsRows(),state.reportTrack)}</div>`}
function currentProfessionalReportHtml(){if(state.reportType==='leaders')return leadersReportHtml();if(state.reportType==='points')return pointsReportHtml();if(state.reportType==='students')return studentsReportHtml();if(state.reportType==='attendance')return attendanceReportHtml();if(state.reportType==='recitations')return recitationsReportHtml();return halaqaReportHtml()}
function reportsPage(){let ready=state.reportLoadedKey===reportKey();return `<div class="report-studio"><div class="hero"><h2>استوديو التقارير</h2><p>تقارير يومية أو لفترة أو لشهر، مع فصل مسار الحفظ العام عن مسار التثبيت وترتيب مستقل لكل مسار.</p></div>${reportFilterHtml()}<div class="report-control-card"><b>نوع التقرير</b>${reportTypeGrid()}</div><div class="report-export-bar"><button class="primary" onclick="openReportPreview()">👁️ معاينة PDF</button><button onclick="exportReportsExcel()">📊 Excel</button><button onclick="exportCurrentReportWord()">📝 Word</button><button onclick="exportCurrentReportImage()">🖼️ PNG</button><button onclick="shareReportText()">↗ مشاركة</button></div>${reportReadySummaryHtml()}<div id="reportExportArea">${ready?currentProfessionalReportHtml():''}</div></div>`}
function reportExportRows(){return reportStatsRows().map((x,i)=>({'#':i+1,'الطالب':x.student.full_name,'الحلقة':state.halaqas.find(h=>h.id===x.student.halaqa_id)?.name||'','الفئة':categoryName(x.student),'المسار':studentTrackAr[x.student.track_code]||'','الفترة':reportPeriodLabel(),'الحفظ':x.hifzPages,'التثبيت':x.tathbitPages,'المراجعة':x.reviewPages,'السرد':x.sardPages,'إجمالي الصفحات':x.totalPages,'النقاط':x.points,'الحضور':x.present,'الغياب':x.absent,'بعذر':x.excused,'التأخر':x.late,'الأخطاء':x.mistakes,'النقرات':x.prompts}))}
async function blobToBase64(blob){return await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]||'');r.onerror=rej;r.readAsDataURL(blob)})}
async function saveOrShareBase64(b64,name,mime){if(isNativeHalaqati()&&window.Capacitor?.Plugins?.Filesystem&&window.Capacitor?.Plugins?.Share){try{let fs=window.Capacitor.Plugins.Filesystem,share=window.Capacitor.Plugins.Share,path='reports/'+name;await fs.writeFile({path,data:b64,directory:'CACHE',recursive:true});let u=await fs.getUri({path,directory:'CACHE'});await share.share({title:name,text:'تقرير من تطبيق حلقتي',url:u.uri,dialogTitle:'حفظ أو مشاركة التقرير'});return}catch(e){console.warn('native share fallback',e)}}let bin=atob(b64),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);downloadBlob(new Blob([arr],{type:mime}),name)}
async function exportReportsExcel(){if(state.reportLoadedKey!==reportKey())return toast('جهّز التقرير أولاً');if(!window.XLSX)return toast('مكتبة Excel لم تُحمّل');let rows=reportExportRows();if(!rows.length)return toast('لا توجد بيانات');let wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'تقرير حلقتي');let name=`تقرير_حلقتي_${reportFileStamp()}.xlsx`;if(isNativeHalaqati()){let b64=XLSX.write(wb,{bookType:'xlsx',type:'base64'});await saveOrShareBase64(b64,name,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}else XLSX.writeFile(wb,name)}
function professionalWordHtml(){return `<!doctype html><html dir="rtl"><head><meta charset="utf-8"><style>body{font-family:Arial,Tahoma,sans-serif;color:#18231f;padding:20px}table{border-collapse:collapse;width:100%;font-size:10px}th{background:#0d3b2f;color:#fff;padding:7px}td{border:1px solid #dfe6e2;padding:6px;text-align:center}.pro-report-page{page-break-after:always;padding:20px}.pro-report-page:last-child{page-break-after:auto}.pro-head{text-align:center;border-bottom:2px solid #c89d4a;padding-bottom:10px}.pro-kpis{display:table;width:100%;margin:10px 0}.pro-kpi{display:table-cell;border:1px solid #ddd;padding:7px;text-align:center}.pro-kpi b{display:block;color:#0d3b2f}</style></head><body>${currentProfessionalReportHtml()}</body></html>`}
async function exportCurrentReportWord(){if(state.reportLoadedKey!==reportKey())return toast('جهّز التقرير أولاً');let blob=new Blob(['\ufeff',professionalWordHtml()],{type:'application/msword'}),name=`تقرير_حلقتي_${reportFileStamp()}.doc`;if(isNativeHalaqati())await saveOrShareBase64(await blobToBase64(blob),name,'application/msword');else downloadBlob(blob,name)}
async function reportCanvas(){if(state.reportLoadedKey!==reportKey())throw new Error('جهّز التقرير أولاً');let el=$('#reportExportArea');if(!el||!el.innerHTML.trim())throw new Error('لا توجد معاينة تقرير');return await html2canvas(el,{scale:1.65,useCORS:true,backgroundColor:'#ffffff',logging:false,windowWidth:Math.max(1100,el.scrollWidth)})}
async function exportCurrentReportImage(){try{let c=await reportCanvas(),blob=await new Promise(r=>c.toBlob(r,'image/png',.96)),name=`تقرير_حلقتي_${reportFileStamp()}.png`;if(isNativeHalaqati())await saveOrShareBase64(await blobToBase64(blob),name,'image/png');else downloadBlob(blob,name)}catch(e){toast('تعذر إنشاء الصورة: '+(e?.message||e))}}
async function exportCurrentReportPdf(){try{if(!window.jspdf?.jsPDF){window.print();return}let c=await reportCanvas(),img=c.toDataURL('image/jpeg',.94),{jsPDF}=window.jspdf,pdf=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'}),pw=297,ph=210,margin=7,w=pw-margin*2,h=c.height*w/c.width,y=margin;pdf.addImage(img,'JPEG',margin,y,w,h);while(y+h>ph-margin){y-=ph-margin*2;pdf.addPage();pdf.addImage(img,'JPEG',margin,y,w,h)}let name=`تقرير_حلقتي_${reportFileStamp()}.pdf`;if(isNativeHalaqati()){let blob=pdf.output('blob');await saveOrShareBase64(await blobToBase64(blob),name,'application/pdf')}else pdf.save(name)}catch(e){toast('تعذر إنشاء PDF: '+(e?.message||e))}}
async function shareReportText(){let rows=reportStatsRows();if(!rows.length)return toast('جهّز التقرير أولاً');let text=`حلقتي — ${reportTypeTitle(state.reportType)}\n${reportTrackLabel()} · ${reportPeriodLabel()}\n`+rows.slice(0,20).map((x,i)=>`${i+1}. ${x.student.full_name}: ${fmt(x.totalPages)} ص · ${fmt(x.points)} نقطة`).join('\n');try{if(navigator.share)await navigator.share({title:'تقرير حلقتي',text});else{await navigator.clipboard.writeText(text);toast('تم نسخ ملخص التقرير')}}catch(e){}}

